const e=[{id:"sv-1-1141",phase:1,topic:"1.3.3",qtype:"concept",difficulty:1,stem:"What does the **return on investment (ROI)** of an improvement project express?",options:["The net benefit gained compared with the cost of the project","The time needed for net benefits to repay the investment","The value of future benefits in today’s money, minus the investment","The share of the process lead time that adds value"],answer:0,hint:"ROI compares what you gain (net of cost) with what you spent.",steps:[{title:"Key idea",body:"ROI relates the **net benefit** (benefit minus cost) to the **cost**, usually as a percentage."},{title:"Apply to the stem",body:"So ROI answers “how much do we get back for each unit we spend?”."},{title:"Eliminate look-alikes",body:"Payback is about time, NPV about today’s value of future money, and process efficiency is not financial."}],final:"ROI = net benefit relative to cost → answer **A**",whyWrong:["","Incorrect — this describes the payback period, which is a time, not a ratio.","Incorrect — this describes net present value (NPV), which discounts future cash flows.","Incorrect — this describes process (flow) efficiency, a Lean measure, not a financial one."],bookRef:"Syllabus 1.3.3"},{id:"sv-1-1142",phase:1,topic:"1.3.3",qtype:"concept",difficulty:1,stem:"Which question does the **payback period** of a solution answer?",options:["How long will it take for net benefits to recover the money invested?","How much net benefit is earned for each unit of cost spent?","What are all the future benefits worth in today’s money?","How far has the primary metric improved against its baseline?"],answer:0,hint:"Payback is measured in time units, not money or percentages.",steps:[{title:"Key idea",body:"The payback period is the **time** until cumulative net benefit equals the investment."},{title:"Apply to the stem",body:"It is quoted in months or years, in the same unit as the benefit rate."},{title:"Eliminate look-alikes",body:"ROI, NPV and percentage improvement answer different questions."}],final:"Payback = time to recover the investment → answer **A**",whyWrong:["","Incorrect — this is the question answered by ROI, a ratio rather than a time.","Incorrect — this is the question answered by net present value (NPV).","Incorrect — this is percentage improvement against the baseline, a process result, not a payback."],bookRef:"Syllabus 1.3.3"},{id:"sv-1-1143",phase:1,topic:"1.3.3",qtype:"concept",difficulty:3,stem:"A solution’s benefits will continue for **five years**. Why would Finance prefer **net present value (NPV)** to a simple payback period when judging it?",options:["NPV values each future benefit in today’s money and counts the whole benefit period","NPV ignores the cost of money, so long-running projects look more attractive","NPV counts only the benefits that arrive before the investment is recovered","NPV shows the benefit as a percentage of the first-year project cost"],answer:0,hint:"Payback stops counting once the money is back; NPV discounts every period’s cash flow.",steps:[{title:"Key idea",body:"**NPV** discounts all future cash flows to today’s value and subtracts the investment, so it uses the **whole** life of the benefit."},{title:"Apply to the stem",body:"For a five-year benefit, payback ignores years after recovery and treats money from year 5 as equal to money today."},{title:"Eliminate look-alikes",body:"Ignoring the cost of money, counting only pre-recovery benefits, and percentage-of-cost all describe other measures or their weaknesses."}],final:"NPV = whole benefit life in today’s money → answer **A**",whyWrong:["","Incorrect — NPV does the opposite: it discounts future money to reflect its cost.","Incorrect — this is the weakness of payback, which ignores benefits after recovery.","Incorrect — a percentage of cost describes ROI, not NPV."],trap:"Payback is quick to explain but ignores both the time value of money and benefits after recovery.",bookRef:"Syllabus 1.3.3"},{id:"sv-1-1144",phase:1,topic:"1.3.3",qtype:"concept",difficulty:2,stem:"In an NPV evaluation, why is a saving received in year 5 counted as worth **less** than the same saving received today?",options:["Savings in later years are always smaller than those in the first year","Money available now can be used or invested, so later money is discounted","Finance counts only the first year of any benefit as hard savings","Benefits after year 1 are cost avoidance and so are not counted in full"],answer:1,hint:"The time value of money.",steps:[{title:"Key idea",body:"NPV applies the **time value of money**: an amount today can be used or invested, so it is worth more than the same amount later."},{title:"Apply to the stem",body:"Each future saving is therefore discounted back to today’s value before being added up."},{title:"Eliminate look-alikes",body:"Size, first-year-only rules and category changes are not the reason."}],final:"Time value of money → discount later savings → answer **B**",whyWrong:["Incorrect — the amounts may be equal; discounting is about timing, not size.","","Incorrect — benefits are tracked over their life; NPV includes every year, discounted.","Incorrect — the benefit category does not change with the year; timing drives the discount."],bookRef:"Syllabus 1.3.3"},{id:"sv-1-1145",phase:1,topic:"1.3.3",qtype:"concept",difficulty:1,stem:"What is the **gross** benefit of a solution?",options:["The benefit that remains after the ongoing costs are subtracted","The benefit after all costs are subtracted and future years discounted","The total cost reduction before any ongoing costs are subtracted","The benefit estimated in the charter before any pilot is run"],answer:2,hint:"Gross = before costs; net = after ongoing costs.",steps:[{title:"Key idea",body:"Because solutions have initial and ongoing costs (book p. 558), benefits are reported **gross** (total cost reduction) and **net** (after ongoing costs)."},{title:"Apply to the stem",body:"The gross figure is the total reduction before anything is subtracted."},{title:"Eliminate look-alikes",body:"Net benefit, NPV and charter estimate are different figures."}],final:"Gross = total reduction before costs → answer **C**",whyWrong:["Incorrect — what remains after ongoing costs is the net benefit.","Incorrect — discounting future years after costs describes NPV.","","Incorrect — the charter figure is an estimate; gross versus net is about costs, not timing."],bookRef:"Book pp. 557–558"},{id:"sv-1-1146",phase:1,topic:"1.3.3",qtype:"concept",difficulty:2,stem:"On what is the benefit estimate in a project charter normally based?",options:["The realised savings confirmed by Finance after Control","The results of the pilot run during the Improve phase","The control limits calculated for the improved process","The baseline cost of poor quality and the improvement goal"],answer:3,hint:"Define: how bad is it now, and how far will we move it?",steps:[{title:"Key idea",body:"In Define the benefit is **estimated** from the **baseline cost of poor quality** and the **goal** — rough on purpose."},{title:"Apply to the stem",body:"Pilot data later validate it; tracking after Control shows the realised figure."},{title:"Eliminate look-alikes",body:"The other sources do not exist yet when the charter is written."}],final:"Charter estimate = baseline COPQ + goal → answer **D**",whyWrong:["Incorrect — realised savings come after Control, long after the charter is written.","Incorrect — pilot results validate the benefit after Improve; the charter comes earlier.","Incorrect — control limits describe process stability, not money, and exist only in Control.",""],bookRef:"Book pp. 499, 577–578"},{id:"sv-1-1147",phase:1,topic:"1.3.3",qtype:"concept",difficulty:1,stem:"Which statement about **percentage improvement** against a baseline is CORRECT?",options:["It is calculated relative to the baseline value, not the new value","It is calculated relative to the target value set in the charter","It must always be reported in currency rather than as a percentage","It shows by itself whether a saving is hard or soft"],answer:0,hint:"Always compare the change with where you started.",steps:[{title:"Key idea",body:"The book lesson’s rule: percentage improvement compares the change with the **baseline** — always divide by the baseline, never by the new value."},{title:"Apply to the stem",body:"The baseline is the starting point the project is judged against."},{title:"Eliminate look-alikes",body:"Target, currency and category are not part of the definition."}],final:"Reference = baseline → answer **A**",whyWrong:["","Incorrect — the goal is not the reference; the change is compared with where the process started.","Incorrect — percentage improvement is a percentage of the baseline, not a money figure.","Incorrect — the category depends on whether spend actually falls, not on the size of the change."],bookRef:"Syllabus 1.3.3"},{id:"sv-1-1148",phase:1,topic:"1.3.3",qtype:"concept",difficulty:3,stem:"Which statement about **ROI** is CORRECT?",options:["ROI is measured in months, so it shows the speed of recovery","A high ROI does not by itself show how quickly the money comes back","ROI ignores the cost of the project and looks only at benefits","ROI and the payback period always rank solutions in the same order"],answer:1,hint:"ROI = how much per unit spent; payback = how fast.",steps:[{title:"Key idea",body:"ROI compares net benefit with cost; it says nothing directly about **timing**."},{title:"Apply to the stem",body:"A big, slow solution can have a higher ROI and a longer payback than a small, fast one."},{title:"Eliminate look-alikes",body:"So high ROI does not show speed of recovery; the other statements misdefine ROI."}],final:"ROI does not measure speed → answer **B**",whyWrong:["Incorrect — ROI is a ratio (often a percentage); time is the payback period.","","Incorrect — ROI compares net benefit with cost, so cost is central to it.","Incorrect — a solution can have the higher ROI but the slower payback, so rankings can differ."],bookRef:"Syllabus 1.3.3"},{id:"sv-1-1149",phase:1,topic:"1.3.3",qtype:"concept",difficulty:2,stem:"Which statement about **net present value (NPV)** is CORRECT?",options:["NPV is measured in months, like the payback period","A negative NPV means the solution pays back very quickly","A positive NPV means the discounted benefits are larger than the investment","NPV ignores when the benefits arrive and counts only their total"],answer:2,hint:"NPV = discounted benefits minus investment, in money.",steps:[{title:"Key idea",body:"NPV discounts future benefits to today’s money and subtracts the investment."},{title:"Apply to the stem",body:"If the result is positive, the discounted benefits exceed what was invested."},{title:"Eliminate look-alikes",body:"The other statements confuse NPV with payback or ignore discounting."}],final:"Positive NPV = benefits exceed investment → answer **C**",whyWrong:["Incorrect — NPV is a money value, not a time.","Incorrect — a negative NPV means discounted benefits fall short of the investment.","","Incorrect — NPV depends on timing, because later money is discounted more."],bookRef:"Syllabus 1.3.3"},{id:"sv-1-1150",phase:1,topic:"1.3.3",qtype:"statements",difficulty:2,stem:`Which statements about financial measures of a solution are CORRECT?

1. ROI compares the net benefit with the cost of the solution.
2. NPV expresses future benefits in today’s money.
3. The payback period is expressed as a percentage.
4. The payback period ignores the size of the initial investment.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"ROI = ratio; NPV = today’s money; payback = time to recover the investment.",steps:[{title:"Key idea",body:"Statement 1 is true (ROI definition) and statement 2 is true (NPV discounts to today’s money)."},{title:"Apply to the stem",body:"Statement 3 is false — payback is a time. Statement 4 is false — the investment is exactly what payback recovers."},{title:"Eliminate look-alikes",body:"So the correct pair is 1 and 2."}],final:"True: 1 and 2 → answer **A**",whyWrong:["","Incorrect — statement 3 is false: payback is a time, such as months.","Incorrect — statements 3 and 4 are both false.","Incorrect — statement 4 is false: payback is the time to recover the initial investment."],bookRef:"Syllabus 1.3.3"},{id:"sv-1-1151",phase:1,topic:"1.3.3",qtype:"statements",difficulty:3,stem:`A project removes three manual steps from invoice processing. Which statements about reporting its savings are CORRECT?

1. The freed clerk hours are soft savings unless spending actually falls.
2. Removing process steps automatically creates hard savings.
3. Freed time should be valued at whatever rate gives the largest figure.
4. If a temporary-staff contract is ended as a result, that cut is a hard saving.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Freed capacity is soft until money stops being spent.",steps:[{title:"Key idea",body:"Statement 1 is true: freed hours are soft unless the business acts on them. Statement 4 is true: ending a paid contract cuts actual spend — hard."},{title:"Apply to the stem",body:"Statement 2 is false (no automatic hard saving); statement 3 is false (method agreed with Finance, honestly)."},{title:"Eliminate look-alikes",body:"So the correct pair is 1 and 4."}],final:"True: 1 and 4 → answer **D**",whyWrong:["Incorrect — statement 2 is false: removing a step frees capacity but does not by itself cut spend.","Incorrect — statements 2 and 3 are both false.","Incorrect — statement 3 is false: the valuation method is agreed with Finance, not chosen to flatter.",""],trap:"“Steps removed × hourly rate” is a capacity figure, not a hard saving, until spend really falls.",bookRef:"Book p. 585"},{id:"sv-1-1152",phase:1,topic:"1.3.3",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Net [?] value converts each future benefit of a solution into today’s money and subtracts the investment.`,options:["future","present","process","project"],answer:1,hint:"NPV — what does the P stand for?",steps:[{title:"Key idea",body:"**Net present value (NPV)** discounts future cash flows to their value today and subtracts the investment."},{title:"Apply to the stem",body:"So the missing word is “present”."},{title:"Eliminate look-alikes",body:"Future, process and project do not complete the measure’s name."}],final:"NPV = net present value → answer **B**",whyWrong:["Incorrect — the method brings future money back to today; “future value” works the other way.","","Incorrect — “net process value” is not a financial measure.","Incorrect — “net project value” is not the name of the discounting measure."],bookRef:"Syllabus 1.3.3"},{id:"sv-1-1153",phase:1,topic:"1.3.3",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A benefit moves from estimated, to validated, to [?] once the gain has lasted and the money has really appeared.`,options:["approved","forecast","realised","targeted"],answer:2,hint:"Three states: estimated → validated → ?",steps:[{title:"Key idea",body:"Benefits are **estimated** in Define, **validated** after Improve and **realised** after Control, when the gain has lasted and the money has appeared."},{title:"Apply to the stem",body:"The sentence describes the final state: realised."},{title:"Eliminate look-alikes",body:"Approved, forecast and targeted are not the book lesson’s states."}],final:"Third state = realised → answer **C**",whyWrong:["Incorrect — approval is a sign-off, not one of the three benefit states.","Incorrect — a forecast is an estimate, which is the first state, not the last.","","Incorrect — a target is the goal in the charter, not a benefit state."],bookRef:"Book pp. 499, 577–578"},{id:"sv-1-1154",phase:1,topic:"1.3.3",qtype:"not-except",difficulty:1,stem:"Which is NOT a measure Finance uses to compare the money value of candidate solutions?",options:["Return on investment","Payback period","Net present value","Process sigma level"],answer:3,hint:"Which option is a process-performance measure, not a money measure?",steps:[{title:"Key idea",body:"ROI, payback and NPV all express a solution’s **money** value in different ways."},{title:"Apply to the stem",body:"Sigma level measures process performance (defects), not financial return."},{title:"Eliminate look-alikes",body:"So sigma level is the odd one out."}],final:"Sigma level is not a financial measure → answer **D**",whyWrong:["Incorrect — ROI compares net benefit with cost, a financial comparison.","Incorrect — payback shows how quickly the investment is recovered, a financial comparison.","Incorrect — NPV gives the discounted money value, a financial comparison.",""],bookRef:"Syllabus 1.3.3"},{id:"sv-1-1155",phase:1,topic:"1.3.3",qtype:"not-except",difficulty:1,stem:"Finance sorts project value into four groups. Which is NOT one of them?",options:["Process capability gain","Hard savings","Cost avoidance","Revenue growth"],answer:0,hint:"Hard, soft, avoidance, revenue.",steps:[{title:"Key idea",body:"The four groups are **hard savings, soft savings, cost avoidance and revenue growth**."},{title:"Apply to the stem",body:"A capability gain is a process result; it may lead to savings but is not a value category itself."},{title:"Eliminate look-alikes",body:"So process capability gain is the odd one out."}],final:"Capability gain is not a value category → answer **A**",whyWrong:["","Incorrect — hard savings (lower actual spend) is one of the four groups.","Incorrect — cost avoidance (future cost prevented) is one of the four groups.","Incorrect — revenue growth (extra income) is one of the four groups."],bookRef:"Book p. 585"},{id:"sv-1-1156",phase:1,topic:"1.3.3",qtype:"scenario",difficulty:3,stem:"Two solutions are on the table. One pays back in 5 months but its benefit fades after a year. The other pays back in 14 months but keeps delivering for five years. The Sponsor wants the **greatest total value over the solution’s life, in today’s money**. How should the solutions be ranked?",options:["By payback period","By net present value","By first-year ROI","By initial cost"],answer:1,hint:"Whole life + today’s money → which measure?",steps:[{title:"Key idea",body:"The Sponsor’s criterion combines **whole-life value** and **today’s money** — the definition of NPV."},{title:"Apply to the stem",body:"NPV discounts each year’s benefit and sums the whole life, so the five-year solution is judged fairly."},{title:"Eliminate look-alikes",body:"Payback, first-year ROI and initial cost each miss part of the criterion."}],final:"Whole-life value in today’s money = NPV → answer **B**",whyWrong:["Incorrect — payback shows speed of recovery and ignores benefits after it, so it favours the short-lived option.","","Incorrect — a first-year ROI ignores the later years in which the second solution keeps paying.","Incorrect — initial cost alone ignores both benefits and timing."],bookRef:"Syllabus 1.3.3"},{id:"sv-1-1157",phase:1,topic:"1.3.3",qtype:"scenario",difficulty:2,stem:"A team removes a weekly courier run that carried paper contracts between two offices. The courier contract is ended, so its monthly invoice stops. Staff also save about 10 hours a week of packing time, with no change to headcount or overtime. Which part of the benefit is a **hard** saving?",options:["Only the staff time saved on packing","Both the ended contract and the time saved","Only the ended courier contract","Neither, because removing a step is cost avoidance"],answer:2,hint:"Which part makes actual spending fall?",steps:[{title:"Key idea",body:"Hard savings need a measurable fall in **actual spend**."},{title:"Apply to the stem",body:"The ended courier contract stops a real invoice → hard. The packing hours are freed with no cost removed → soft."},{title:"Eliminate look-alikes",body:"So only the contract counts as hard."}],final:"Ended invoice = hard; freed hours = soft → answer **C**",whyWrong:["Incorrect — the packing hours are freed capacity with no spend removed, so they are soft.","Incorrect — only the contract removes actual spend; the hours are soft savings.","","Incorrect — the courier invoice was being paid and has stopped, so it is not a future cost avoided."],bookRef:"Book p. 585"},{id:"sv-1-1158",phase:1,topic:"1.3.3",qtype:"scenario",difficulty:3,stem:"A Green Belt divides a solution’s one-off cost by its **annual** net benefit and gets 0.25. She reports “payback = 0.25 months”. What is wrong with this report?",options:["The result is a percentage and should be shown as 25%","The result is the ROI of the solution, not its payback","The result has no unit, because payback is a pure ratio","The result is in years, because the benefit rate was annual"],answer:3,hint:"Payback carries the time unit of the benefit rate.",steps:[{title:"Key idea",body:"Payback = investment divided by net benefit **per period**, so its unit is the period of the benefit."},{title:"Apply to the stem",body:"An annual benefit gives an answer in **years**; 0.25 is a quarter of a year, not 0.25 months."},{title:"Eliminate look-alikes",body:"Keep time units consistent — the book lesson flags exactly this trap."}],final:"Annual rate → answer in years",whyWrong:["Incorrect — payback is a time, not a percentage.","Incorrect — ROI compares net benefit with cost; this division gives a recovery time.","Incorrect — payback always carries the time unit of the benefit rate.",""],trap:"Dividing by an annual benefit gives years; dividing by a monthly benefit gives months.",bookRef:"Syllabus 1.3.3"},{id:"sv-1-1159",phase:1,topic:"1.3.3",qtype:"best-action",difficulty:2,stem:`After a two-week pilot, the Green Belt reports the charter’s full estimate of **OMR 200,000 a year** as a *realised* benefit at the Improve tollgate.

Was this an appropriate action?`,options:["Yes, because a successful pilot proves the benefit for the whole year","Yes, because the Sponsor owns the financial figures of the project","No, because a benefit is realised only after the gain is sustained and tracked","No, because financial benefits may be reported only in the Define phase"],answer:2,hint:"Estimated (Define) → validated (after Improve) → realised (after Control).",steps:[{title:"Key idea",body:"Benefits pass through three states: **estimated**, **validated** (pilot data, method agreed with Finance) and **realised** (gain sustained, money appears, tracked about 12 months)."},{title:"Apply to the stem",body:"At the Improve tollgate after a pilot the figure can only be validated, not realised."},{title:"Eliminate look-alikes",body:"So the action was not appropriate, and the reason is the realisation timing."}],final:"Pilot = validated, not realised → answer **C**",whyWrong:["Incorrect — a pilot validates the effect; ramp-up and sustainment still have to be proven.","Incorrect — Finance, not the Sponsor alone, validates figures; ownership does not make a pilot figure realised.","","Incorrect — benefits are estimated in Define and tracked through Control; reporting is not limited to Define."],bookRef:"Book pp. 499, 577–578"},{id:"sv-1-1160",phase:1,topic:"1.3.3",qtype:"best-action",difficulty:3,stem:`Two solutions are compared. Solution X has a large yearly software licence; Solution Y has none. The Green Belt ranks them by **gross** annual benefit only and recommends X.

Was this an appropriate action?`,options:["Yes, because gross benefit shows the full potential of each solution","Yes, because licence costs belong to the IT budget, not the project","No, because financial benefits must be calculated by Finance only","No, because the ongoing licence cost reduces the net benefit of Solution X"],answer:3,hint:"Compare solutions on net benefit (after ongoing costs).",steps:[{title:"Key idea",body:"Book pp. 557–558: costs are initial and ongoing; a cost-benefit analysis weighs them against impact."},{title:"Apply to the stem",body:"A yearly licence is an ongoing cost, so X’s net benefit is lower than its gross figure suggests."},{title:"Eliminate look-alikes",body:"The ranking should use net benefit, so the action was not appropriate."}],final:"Rank by net, not gross → answer **D**",whyWrong:["Incorrect — gross ignores ongoing costs, so it can rank an expensive-to-run solution too high.","Incorrect — every cost of running the solution counts against its benefit, whichever budget pays.","Incorrect — Finance validates the figures, but the Belt still prepares the cost-benefit comparison.",""],bookRef:"Book pp. 557–558"},{id:"sv-1-1161",phase:1,topic:"1.3.3",qtype:"best-action",difficulty:2,stem:"At the Control tollgate, the Green Belt is about to move to a new project. The realised benefit has been tracked for only two months. What is the BEST action?",options:["Hand over to the Process Owner and agree that Finance keeps tracking the realised benefit","Stop tracking the benefit, because the project is now closing","Scale the two months up to a full year and book it as realised","Keep the project open until the Belt has personally tracked 12 months"],answer:0,hint:"Process Owner keeps the gain; Champion signs; Finance records the realised figure.",steps:[{title:"Key idea",body:"Good hand-over: the **Process Owner** keeps the gain, the Champion signs, and **Finance** records the realised figure, tracking for about 12 months."},{title:"Apply to the stem",body:"The book lists “financial benefits are not tracked and integrated into the business” as a Control roadblock (p. 577)."},{title:"Eliminate look-alikes",body:"Stopping, extrapolating or holding the project open are all weaker choices."}],final:"Hand over; Finance keeps tracking → answer **A**",whyWrong:["","Incorrect — the book lists untracked financial benefits as a Control roadblock.","Incorrect — two months may include ramp-up; projecting them is not a realised figure.","Incorrect — tracking continues after hand-over; the Belt need not hold the project open."],bookRef:"Book pp. 499, 577–578"},{id:"sv-1-1162",phase:1,topic:"1.3.3",qtype:"output",difficulty:3,stem:`Finance summarises three candidate solutions:

\`\`\`
Solution  Initial cost  Net benefit/yr  Payback (months)  ROI yr 1
   A          20,000          60,000              4             200%
   B          90,000         300,000              9             233%
   C          30,000          45,000              8              50%
\`\`\`

The Sponsor wants the solution that **recovers its investment fastest**. Which should be chosen?`,options:["Solution B, because it has the highest first-year ROI","Solution A, because it has the shortest payback period","Solution B, because it has the largest yearly net benefit","Solution A, because it has the lowest initial cost"],answer:1,hint:"Speed of recovery = payback period (a time).",steps:[{title:"Key idea",body:"Payback answers “how long until the investment is recovered?”. ROI answers “how much per unit spent?”."},{title:"Apply to the stem",body:"The table prints payback directly: A = 4 months, B = 9, C = 8. A is fastest."},{title:"Eliminate look-alikes",body:"B wins on ROI and total benefit, but those answer different questions."}],final:"Fastest recovery = shortest payback = A → answer **B**",whyWrong:["Incorrect — ROI compares benefit with cost; it does not measure how quickly money is recovered.","","Incorrect — the largest benefit answers “which earns most”, not “which pays back fastest”.","Incorrect — A is right, but low initial cost alone does not show recovery speed; C’s cost is close yet slower."],trap:"Choose the right reason, not just the right solution: the fastest recovery is shown by payback, not initial cost.",bookRef:"Syllabus 1.3.3"},{id:"sv-1-1163",phase:1,topic:"1.3.3",qtype:"output",difficulty:2,stem:`Finance’s benefit register shows four projects:

\`\`\`
Project  Phase completed   Benefit status   Months tracked
   A       Control          Realised              12
   B       Improve          Validated              0
   C       Define           Estimated              0
   D       Control          Validated              3
\`\`\`

Which project’s benefit can be reported as **realised** in the annual report?`,options:["Project B, because its pilot results have been validated","Project D, because the project has completed Control","Project A, because Finance has tracked it for 12 months after Control","Project C, because its charter estimate has been approved"],answer:2,hint:"Estimated → validated → realised; read the status and tracking columns.",steps:[{title:"Key idea",body:"Only Project A shows status **Realised**, with 12 months of tracking after Control."},{title:"Apply to the stem",body:"B and D are Validated (D has only 3 months tracked); C is an estimate from Define."},{title:"Eliminate look-alikes",body:"So only A can be reported as realised."}],final:"Realised = A → answer **C**",whyWrong:["Incorrect — a validated pilot benefit is not yet realised; the register shows it as Validated.","Incorrect — completing Control is not enough; only 3 months are tracked and the status is Validated.","","Incorrect — a charter figure is only an estimate."],bookRef:"Book pp. 499, 577–578"},{id:"sv-1-1164",phase:1,topic:"1.3.3",qtype:"true-false",difficulty:2,stem:"A solution with a shorter payback period always has a higher ROI than a solution with a longer payback period.",options:["True","False"],answer:1,hint:"Speed of recovery and size of return are different questions.",steps:[{title:"Key idea",body:"Payback answers “how fast is the money back?”; ROI answers “how much is returned per unit of cost?”."},{title:"Apply to the stem",body:"A large, slower solution can have a longer payback **and** a higher ROI, so “always” is false."}],final:"The statement is false → answer **B**",whyWrong:["Incorrect — payback measures speed and ROI measures return per unit cost; a slower solution can still have the higher ROI.",""],bookRef:"Syllabus 1.3.3"},{id:"sv-1-1165",phase:1,topic:"1.4.1",qtype:"concept",difficulty:1,stem:"In Lean thinking, from whose point of view is **value** defined?",options:["The process owner","Senior management","The improvement team","The customer"],answer:3,hint:"Lean sees work “through the customer’s eyes”.",steps:[{title:"Key idea",body:"In Lean, value is what the **customer** recognises and would willingly pay for — never what the organisation thinks is valuable."},{title:"Apply to the stem",body:"The stem asks whose viewpoint defines value: the customer’s."},{title:"Eliminate look-alikes",body:"Owner, management and team all work to the customer’s definition."}],final:"Value is defined by the customer → answer **D**",whyWrong:["Incorrect — the process owner manages the process but does not decide what the customer values.","Incorrect — management priorities matter, but Lean value is what the customer recognises and pays for.","Incorrect — the team analyses steps against the customer’s view; it does not define value itself.",""],bookRef:"Book pp. 117, 587"},{id:"sv-1-1166",phase:1,topic:"1.4.1",qtype:"concept",difficulty:1,stem:"Which pair of tests does the book use to decide whether a process step is **value-added**?",options:["It changes form, fit or function, and the customer is willing to pay for it","It is completed quickly, and it uses few resources","It is required by law, and it is fully documented","It is done by skilled staff, and its output is checked"],answer:0,hint:"Book p. 117: two questions about the product and about the customer.",steps:[{title:"Key idea",body:"Book p. 117: a step is value-added if it **changes the form, fit or function** of the product or service **and** the customer is **willing to pay** for it."},{title:"Apply to the stem",body:"Both tests must be passed."},{title:"Eliminate look-alikes",body:"Speed, legal need and staff skill are not the tests."}],final:"VA = changes form/fit/function + customer pays → answer **A**",whyWrong:["","Incorrect — speed and low resource use describe efficiency, not whether a step adds value.","Incorrect — a legal requirement makes a step business-value-added at best, not value-added.","Incorrect — skill and checking do not change the product; checking is never value-added."],bookRef:"Book p. 117"},{id:"sv-1-1167",phase:1,topic:"1.4.1",qtype:"concept",difficulty:1,stem:"Which describes a **business-value-added** activity?",options:["Work that changes the service and that the customer pays for","Work the customer would not pay for, but the business must do","Work that adds nothing and can simply be removed","Work done only to keep people busy between orders"],answer:1,hint:"Three groups: VA, NVA, and required-but-not-valued.",steps:[{title:"Key idea",body:"Business-value-added (BVA) steps fail the customer test but are **required** — legal, regulatory, safety or contract."},{title:"Apply to the stem",body:"The description that matches is “the customer would not pay, but the business must do it”."},{title:"Eliminate look-alikes",body:"VA passes both tests; NVA and busy-work are removable waste."}],final:"BVA = required but not valued by the customer → answer **B**",whyWrong:["Incorrect — this is value-added work, which passes both tests.","","Incorrect — this is pure non-value-added work, which is eliminated.","Incorrect — busy-work is waste (non-value-added), not something the business requires."],bookRef:"Book p. 117"},{id:"sv-1-1168",phase:1,topic:"1.4.1",qtype:"concept",difficulty:2,stem:"How should a business-value-added step be treated in a Lean improvement?",options:["By eliminating it at once as pure waste","By keeping and expanding it as value-added work","By minimising and simplifying it, without deleting it","By moving it to the end of the process"],answer:2,hint:"Required steps stay, but as small as possible.",steps:[{title:"Key idea",body:"NVA → eliminate; BVA → **minimise and simplify**; VA → keep and improve."},{title:"Apply to the stem",body:"The book (p. 117) agrees that some non-value activities, such as data collection for regulations, cannot be removed."},{title:"Eliminate look-alikes",body:"Deleting, expanding or relocating it does not match the rule."}],final:"BVA → minimise, do not delete → answer **C**",whyWrong:["Incorrect — elimination is for pure NVA; a required step cannot simply be removed.","Incorrect — the customer would not pay for it, so it should not be expanded.","","Incorrect — moving a step does not reduce its effort; the aim is to minimise it."],bookRef:"Book p. 117"},{id:"sv-1-1169",phase:1,topic:"1.4.1",qtype:"concept",difficulty:1,stem:"The book glossary defines **waste** as material, effort and time that does not add value in the eyes of which group?",options:["Only the members of the Six Sigma project team","Only the regulator and the external auditors","Only the Finance department of the organisation","Key stakeholders such as customers, employees and investors"],answer:3,hint:"Book p. 590 names three stakeholder groups.",steps:[{title:"Key idea",body:"Book glossary p. 590: waste is material, effort and time that does not add value in the eyes of **key stakeholders — customers, employees and investors**."},{title:"Apply to the stem",body:"The question asks whose eyes; the answer is that wider stakeholder group."},{title:"Eliminate look-alikes",body:"The team, the regulator and Finance are each too narrow."}],final:"Waste = no value for customers, employees, investors → answer **D**",whyWrong:["Incorrect — the team identifies waste, but the definition refers to key stakeholders.","Incorrect — regulators drive business-value-added steps, but they are not the reference for waste.","Incorrect — Finance validates savings; the glossary names customers, employees and investors.",""],bookRef:"Book p. 590"},{id:"sv-1-1170",phase:1,topic:"1.4.1",qtype:"concept",difficulty:2,stem:"When studying a process, what does Lean mainly watch?",options:["The work item, to see where it waits and how it flows","Each person, to check that everyone is busy all day","Each machine, to measure how fast it runs alone","Each team, to count how many staff it employs"],answer:0,hint:"“Follow the ticket, not the engineer.”",steps:[{title:"Key idea",body:"Lean watches the **work item** (the ticket, order or invoice), not how busy the resources are."},{title:"Apply to the stem",body:"A desk where every agent is 100% busy can still give poor service if tickets wait between them."},{title:"Eliminate look-alikes",body:"Watching people, machines or headcount is the traditional resource view."}],final:"Lean follows the work item → answer **A**",whyWrong:["","Incorrect — keeping people busy is resource efficiency; busy people can still leave work queuing.","Incorrect — machine speed alone ignores the queues between steps.","Incorrect — headcount does not show whether value flows to the customer."],bookRef:"Syllabus 1.4.1"},{id:"sv-1-1171",phase:1,topic:"1.4.1",qtype:"concept",difficulty:2,stem:"What does the book mean by **kaikaku**?",options:["Continual small improvements made by everyone","A breakthrough improvement that gives a large, sudden gain","A visual signal that tells a step to begin work","A device that makes an error impossible to make"],answer:1,hint:"Kaizen = continual; kaikaku = breakthrough.",steps:[{title:"Key idea",body:"Book p. 510: **kaizen** is continual improvement; **kaikaku** describes **breakthrough** successes."},{title:"Apply to the stem",body:"The definition asked for is the breakthrough one."},{title:"Eliminate look-alikes",body:"Kanban and poka-yoke are other Japanese Lean terms with different meanings."}],final:"Kaikaku = breakthrough → answer **B**",whyWrong:["Incorrect — continual small improvement is kaizen.","","Incorrect — a signal to begin work is kanban.","Incorrect — making an error impossible is poka-yoke (mistake-proofing)."],bookRef:"Book p. 510"},{id:"sv-1-1172",phase:1,topic:"1.4.1",qtype:"concept",difficulty:1,stem:"What does **process (flow) efficiency** measure?",options:["The share of each person’s day spent working on tasks","The value-added time divided by the non-value-added time only","The share of the total lead time that is value-added time","The number of units completed in each hour of work"],answer:2,hint:"Value-added time compared with all the time the item spends in the process.",steps:[{title:"Key idea",body:"Process efficiency = value-added time divided by **total lead time**."},{title:"Apply to the stem",body:"It shows how much of the item’s time in the process actually adds value."},{title:"Eliminate look-alikes",body:"Utilisation, a VA/NVA ratio and throughput are different measures."}],final:"Flow efficiency = VA time ÷ total lead time → answer **C**",whyWrong:["Incorrect — this is resource efficiency (utilisation), which Lean does not use to judge flow.","Incorrect — the denominator must be the total lead time, not only the NVA time.","","Incorrect — units per hour is throughput or productivity, not flow efficiency."],trap:"Dividing VA time by NVA time only is a common slip; use the total lead time.",bookRef:"Syllabus 1.4.1"},{id:"sv-1-1173",phase:1,topic:"1.4.1",qtype:"concept",difficulty:2,stem:"Which statement about **inspection and approval** steps is CORRECT?",options:["They are value-added because they protect the customer from defects","They are value-added when they are done by senior staff","They must always be eliminated at once as pure waste","They do not change form, fit or function, so at best they are business-value-added"],answer:3,hint:"Apply the form, fit or function test to a check.",steps:[{title:"Key idea",body:"Inspection and approval do **not** change the form, fit or function of the product, so they are never value-added."},{title:"Apply to the stem",body:"Where a law or contract requires them they are business-value-added (minimise); otherwise they are NVA."},{title:"Eliminate look-alikes",body:"So “at best BVA” is the correct statement."}],final:"Checks are never VA; at best BVA → answer **D**",whyWrong:["Incorrect — protection is not a change to the product; inspection fails the form, fit or function test.","Incorrect — who does a step does not change whether it adds value.","Incorrect — some checks are required (BVA) and must be minimised, not deleted.",""],bookRef:"Book p. 117"},{id:"sv-1-1174",phase:1,topic:"1.4.1",qtype:"concept",difficulty:2,stem:"Which statement about the **five Lean principles** is CORRECT?",options:["Value must be defined before the value stream can be mapped","Flow should be designed before the value stream is known","Pull means producing goods according to a sales forecast","Perfection is a one-off target reached when a project closes"],answer:0,hint:"Value → value stream → flow → pull → perfection, in that order.",steps:[{title:"Key idea",body:"The five principles run **value → value stream → flow → pull → perfection**, and each needs the one before it."},{title:"Apply to the stem",body:"You cannot map the value stream until value has been defined from the customer’s view."},{title:"Eliminate look-alikes",body:"The other statements reverse the order or misdefine pull and perfection."}],final:"Define value first → answer **A**",whyWrong:["","Incorrect — flow can only be designed once the value stream is known.","Incorrect — pull means working only on real downstream demand; forecasts drive push.","Incorrect — perfection means continuous improvement that never ends."],bookRef:"Syllabus 1.4.1"},{id:"sv-1-1175",phase:1,topic:"1.4.1",qtype:"concept",difficulty:3,stem:"Which statement about Lean and **respect for people** is CORRECT?",options:["Waste is usually caused by careless individuals who need closer supervision","Waste is usually a feature of the system, so the people doing the work help find it","Lean improvement is best done by experts without involving the operators","Respect for people means keeping existing habits so staff are not upset"],answer:1,hint:"Blame the system, involve the people.",steps:[{title:"Key idea",body:"Lean rests on **respect for people**: waste is nearly always a feature of the **system** — poor hand-offs, unclear standards, batching."},{title:"Apply to the stem",body:"The people doing the work usually see the waste first, so Lean improvement involves them."},{title:"Eliminate look-alikes",body:"Blaming individuals, excluding operators or freezing habits all contradict this."}],final:"System causes waste; people help find it → answer **B**",whyWrong:["Incorrect — Lean sees waste mainly as a system problem (hand-offs, standards, batching), not personal blame.","","Incorrect — operators usually see the waste first, so Lean involves them.","Incorrect — respect means involving people in improvement, not protecting wasteful habits."],bookRef:"Syllabus 1.4.1"},{id:"sv-1-1176",phase:1,topic:"1.4.1",qtype:"statements",difficulty:2,stem:`Which statements about **value-added** work are CORRECT?

1. Rework is value-added because it fixes the output.
2. Value is defined by the customer.
3. A step is value-added only if the customer is willing to pay for it.
4. Approval steps are value-added because they reduce risk.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Customer defines value; VA must pass the customer-pays test.",steps:[{title:"Key idea",body:"Statement 2 is true (value is defined by the customer) and statement 3 is true (the customer-pays test, book p. 117)."},{title:"Apply to the stem",body:"Statement 1 is false: rework corrects an error and is waste. Statement 4 is false: approvals never change form, fit or function."},{title:"Eliminate look-alikes",body:"So the correct pair is 2 and 3."}],final:"True: 2 and 3 → answer **B**",whyWrong:["Incorrect — statement 1 is false: rework (a “re-” activity) is waste.","","Incorrect — statement 4 is false: approvals do not change form, fit or function.","Incorrect — statements 1 and 4 are both false."],bookRef:"Book p. 117"},{id:"sv-1-1177",phase:1,topic:"1.4.1",qtype:"statements",difficulty:3,stem:`Which statements about **lead time** are CORRECT?

1. Lead time is the same as cycle time.
2. Lead time counts only the value-added time.
3. Lead time includes the time a unit waits between steps.
4. Cutting waiting usually gives a bigger gain than speeding up the work.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Lead time = entry to exit, including all the waiting.",steps:[{title:"Key idea",body:"Lead time is the **total** time a unit spends in the process, from entry to exit, including waiting (statement 3 true)."},{title:"Apply to the stem",body:"Because waiting is usually most of the lead time, attacking waiting gives the bigger gain (statement 4 true)."},{title:"Eliminate look-alikes",body:"Statements 1 and 2 confuse lead time with cycle time and VA time. Correct pair: 3 and 4."}],final:"True: 3 and 4 → answer **C**",whyWrong:["Incorrect — statements 1 and 2 are both false.","Incorrect — statement 2 is false: lead time is total elapsed time, not just VA time.","","Incorrect — statement 1 is false: cycle time is the time per unit at a step."],bookRef:"Syllabus 1.4.1"},{id:"sv-1-1178",phase:1,topic:"1.4.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing words in the following sentence.

A step that does not change the form, fit or function of the service, that the customer would not pay for, and that no law or contract requires, is a [?] step.`,options:["business-value-added","non-value-added","value stream","value-added"],answer:1,hint:"Fails both tests and is not required → which label?",steps:[{title:"Key idea",body:"NVA = fails the form, fit or function test and the customer-pays test (book glossary p. 587)."},{title:"Apply to the stem",body:"The sentence also says no law or contract requires it, which rules out business-value-added."},{title:"Eliminate look-alikes",body:"So the step is non-value-added and should be eliminated."}],final:"Not valued, not required → NVA → answer **B**",whyWrong:["Incorrect — business-value-added steps are required by law, regulation or contract; this step is not.","","Incorrect — the value stream is the whole set of steps delivering value, not one type of step.","Incorrect — value-added steps pass both tests; this one fails both."],bookRef:"Book pp. 117, 587"},{id:"sv-1-1179",phase:1,topic:"1.4.1",qtype:"missing-word",difficulty:2,stem:`Identify the missing words in the following sentence.

Lean judges a process by how smoothly the [?] moves through it, not by how busy the people are.`,options:["budget","machine","staff","work item"],answer:3,hint:"“Follow the ticket, not the engineer.”",steps:[{title:"Key idea",body:"Lean shifts the viewpoint from the **resource** to the **work item** — the ticket, order or invoice."},{title:"Apply to the stem",body:"The sentence contrasts what moves with how busy people are; the word is “work item”."},{title:"Eliminate look-alikes",body:"Budget, machine and staff are resource views."}],final:"Follow the work item → answer **D**",whyWrong:["Incorrect — the budget is not what flows through the process to the customer.","Incorrect — machine utilisation is a resource view; Lean watches what flows.","Incorrect — watching how busy staff are is exactly the resource view Lean replaces.",""],bookRef:"Syllabus 1.4.1"},{id:"sv-1-1180",phase:1,topic:"1.4.1",qtype:"not-except",difficulty:3,stem:"A team reviews four activities at a mobile operator. Which activity should NOT be classed as business-value-added?",options:["Reporting a major network outage to the telecom regulator","Verifying a customer’s identity document before a SIM swap","Re-entering order details that are already held in the CRM","Keeping call records for the period that the law requires"],answer:2,hint:"Ask: who requires this, and where is it written?",steps:[{title:"Key idea",body:"BVA steps are required by law, regulation, safety or contract even though the customer would not pay for them."},{title:"Apply to the stem",body:"Re-entering data that is already held is required by nobody — it is NVA (and a “re-” activity)."},{title:"Eliminate look-alikes",body:"The other three are required by regulation or law."}],final:"Re-entry is NVA, not BVA → answer **C**",whyWrong:["Incorrect — outage reporting is required by the regulator, so it is BVA.","Incorrect — the ID check is a regulatory requirement, so it is BVA.","","Incorrect — retention required by law is BVA: minimise it, but it cannot be removed."],bookRef:"Book p. 117"},{id:"sv-1-1181",phase:1,topic:"1.4.1",qtype:"not-except",difficulty:1,stem:"A team labels several steps as **business-value-added**. Which reason does NOT justify that label?",options:["A regulator requires the step to be performed","A customer contract demands the step","A safety rule requires the step","The team has always done the step this way"],answer:3,hint:"Be sceptical of the BVA label: habit is not a requirement.",steps:[{title:"Key idea",body:"BVA = required by law, regulation, safety or contract."},{title:"Apply to the stem",body:"Teams often defend habits as “required”; habit is not written anywhere, so it does not justify BVA."},{title:"Eliminate look-alikes",body:"Regulation, contract and safety are all real requirements."}],final:"Habit does not make a step BVA → answer **D**",whyWrong:["Incorrect — a regulatory requirement is a valid reason for BVA.","Incorrect — a contractual requirement is a valid reason for BVA.","Incorrect — a safety requirement is a valid reason for BVA.",""],bookRef:"Book p. 117"},{id:"sv-1-1182",phase:1,topic:"1.4.1",qtype:"scenario",difficulty:2,stem:"A service desk closes tickets very quickly, but many customers call back because their faults were not actually fixed. Which description fits this desk?",options:["Efficient but not effective","Effective but not efficient","Both effective and efficient","Neither effective nor efficient"],answer:0,hint:"Effectiveness = right things; efficiency = things done right (fast, cheap).",steps:[{title:"Key idea",body:"**Effectiveness** = doing the right things (the outcome the customer needs). **Efficiency** = doing things right with the least time and effort."},{title:"Apply to the stem",body:"Fast closures are efficient; unfixed faults mean it is not effective."},{title:"Eliminate look-alikes",body:"Lean wants both, and starts with effectiveness."}],final:"Fast but unfixed → efficient, not effective → answer **A**",whyWrong:["","Incorrect — effective means doing the right thing (fixing the fault), which the desk fails to do.","Incorrect — the faults are not fixed, so the desk is not effective.","Incorrect — the desk is fast, so it is efficient in the narrow sense."],bookRef:"Syllabus 1.4.1"},{id:"sv-1-1183",phase:1,topic:"1.4.1",qtype:"scenario",difficulty:3,stem:"A supervisor re-reads every customer order after the system has already validated it. When asked, nobody can name a law, contract or customer request for this check. How should the step be classified?",options:["Business-value-added","Non-value-added","Value-added","Value stream"],answer:1,hint:"Who requires it, and where is it written? If no one — it is NVA.",steps:[{title:"Key idea",body:"Inspection steps are never value-added; at best they are BVA, and only if something requires them."},{title:"Apply to the stem",body:"Here nothing requires the check and the system already validates the order, so it is **non-value-added** — eliminate it."},{title:"Eliminate look-alikes",body:"Calling it BVA is the habit-defending trap the book warns against."}],final:"Unrequired re-check = NVA → answer **B**",whyWrong:["Incorrect — BVA needs a real legal, regulatory, safety or contract requirement; none exists.","","Incorrect — re-reading does not change form, fit or function, so it is never VA.","Incorrect — the value stream is the whole set of steps, not a classification of one step."],trap:"A check that “feels important” is not BVA unless a law, contract or safety rule requires it.",bookRef:"Book p. 117"},{id:"sv-1-1184",phase:1,topic:"1.4.1",qtype:"scenario",difficulty:1,stem:"At a field depot, spare routers are now released only when a real fault ticket requests one, instead of by a monthly forecast. Which Lean principle is being applied?",options:["Flow","Perfection","Pull","Value stream"],answer:2,hint:"Work started by real downstream demand, not a forecast.",steps:[{title:"Key idea",body:"**Pull** means work only on real demand — spares released by actual faults, not forecasts."},{title:"Apply to the stem",body:"Replacing forecast-driven release with demand-driven release is pull."},{title:"Eliminate look-alikes",body:"Flow, perfection and value stream are the other principles."}],final:"Demand-triggered release = pull → answer **C**",whyWrong:["Incorrect — flow is about moving value-added steps without stopping, not about what triggers release.","Incorrect — perfection is continuous improvement, not a release rule.","","Incorrect — the value stream is the end-to-end set of steps; it is not a trigger for work."],bookRef:"Syllabus 1.4.1"},{id:"sv-1-1185",phase:1,topic:"1.4.1",qtype:"scenario",difficulty:2,stem:"A team removes the queues between three resolver groups, so a ticket now moves from diagnosis to fix without stopping. Which Lean principle does this BEST illustrate?",options:["Flow","Perfection","Pull","Value"],answer:0,hint:"Value-added steps moving without stopping.",steps:[{title:"Key idea",body:"**Flow** = make the value-added steps move without stopping — remove queues, route correctly first time."},{title:"Apply to the stem",body:"Taking out the waits between resolver groups lets the ticket move continuously."},{title:"Eliminate look-alikes",body:"Pull, value and perfection are different principles."}],final:"No-stop movement = flow → answer **A**",whyWrong:["","Incorrect — perfection is the ongoing pursuit of improvement, not removing a queue once.","Incorrect — pull is about starting work only on demand; the change here removes stops between steps.","Incorrect — value is defining what the customer values; it is the first principle, not this action."],bookRef:"Syllabus 1.4.1"},{id:"sv-1-1186",phase:1,topic:"1.4.1",qtype:"best-action",difficulty:3,stem:`A fibre order takes **10 days** from request to activation, but only **6 hours** of work actually change the service. The manager decides to buy faster test equipment to shorten those 6 hours.

Was this an appropriate action?`,options:["Yes, because value-added work is always the first target of Lean","Yes, because faster equipment shortens every step of the process","No, because the testing step is non-value-added and should be removed","No, because most of the lead time is waiting, so that is the bigger target"],answer:3,hint:"Where is most of the lead time spent?",steps:[{title:"Key idea",body:"Process efficiency is tiny here: a few hours of value-added work in a lead time of days. Almost all the time is waiting and hand-offs."},{title:"Apply to the stem",body:"The biggest gains come from attacking **waiting**, not from making the few hours of work faster."},{title:"Eliminate look-alikes",body:"So the action was not appropriate, because it targets the small VA portion."}],final:"Attack waiting, not the VA hours → answer **D**",whyWrong:["Incorrect — Lean keeps VA work and attacks the waste around it first.","Incorrect — equipment speeds only the test step; queues and hand-offs stay the same.","Incorrect — testing that changes the service is part of the VA work; removing it is not the point.",""],bookRef:"Syllabus 1.4.1"},{id:"sv-1-1187",phase:1,topic:"1.4.1",qtype:"best-action",difficulty:2,stem:"A team wants to apply Lean thinking to an insurance-claims process. What should it do FIRST?",options:["Design pull signals between the claims teams","Set up continuous flow across all the claims desks","Define what the customer values in the claims process","Launch daily reviews to pursue perfection"],answer:2,hint:"Five principles in order: value, value stream, flow, pull, perfection.",steps:[{title:"Key idea",body:"The principles run **value → value stream → flow → pull → perfection**."},{title:"Apply to the stem",body:"The first job is to define value from the customer’s view."},{title:"Eliminate look-alikes",body:"Pull, flow and perfection come later."}],final:"Start with value → answer **C**",whyWrong:["Incorrect — pull is the fourth principle; it needs value, value stream and flow first.","Incorrect — flow is the third principle; you cannot design it before value and the value stream.","","Incorrect — perfection is the last principle, the ongoing loop after the others."],bookRef:"Syllabus 1.4.1"},{id:"sv-1-1188",phase:1,topic:"1.4.1",qtype:"output",difficulty:2,stem:`A team classifies the steps of a business-line order:

\`\`\`
Step                         Type   Minutes
Capture order details         VA       12
Wait for credit check         NVA     240
Record data for regulator     BVA       8
Re-enter order in billing     NVA      15
Configure line                VA       35
\`\`\`

Which step should be **minimised and simplified, but not removed**?`,options:["Wait for credit check","Re-enter order in billing","Configure line","Record data for regulator"],answer:3,hint:"NVA → eliminate; BVA → minimise; VA → keep.",steps:[{title:"Key idea",body:"The rule: VA keep and improve, NVA eliminate, **BVA minimise and simplify**."},{title:"Apply to the stem",body:"The only step marked BVA in the output is “Record data for regulator”."},{title:"Eliminate look-alikes",body:"The waiting and re-entry steps are NVA; configuring the line is VA."}],final:"BVA step = Record data for regulator → answer **D**",whyWrong:["Incorrect — this is NVA waiting and should be eliminated or cut hard.","Incorrect — this is NVA (a “re-” activity) and should be eliminated.","Incorrect — this is VA work, which is kept and improved, not minimised.",""],bookRef:"Book p. 117"},{id:"sv-1-1189",phase:1,topic:"1.4.1",qtype:"output",difficulty:3,stem:`A value stream walk of 30 enterprise orders gives:

\`\`\`
Descriptive Statistics: Order-to-activation (hours)

Variable          N    Mean
Lead time        30   52.0
Value-added      30    1.3
Waiting          30   46.0

Process efficiency (mean) = 2.5%
\`\`\`

Which conclusion is BEST supported by this output?`,options:["Most of the lead time is non-value-added, so waiting is the main target","The process is efficient because the value-added time is short","Speeding up the value-added work will give the largest gain","Lead time and cycle time are the same for this process"],answer:0,hint:"Read the printed process efficiency and the waiting line.",steps:[{title:"Key idea",body:"The output prints process efficiency of **2.5%**: almost all of the 52-hour lead time adds no value."},{title:"Apply to the stem",body:"Waiting alone is 46.0 hours, so the biggest gain comes from attacking waiting."},{title:"Eliminate look-alikes",body:"The other options misread efficiency or confuse lead time with cycle time."}],final:"Waiting dominates → attack waiting → answer **A**",whyWrong:["","Incorrect — a short VA time inside a long lead time means low flow efficiency, not high.","Incorrect — VA is only 1.3 of 52 hours; halving it would barely change lead time.","Incorrect — lead time includes waiting; cycle time is the time per unit at a step."],bookRef:"Syllabus 1.4.1"},{id:"sv-1-1190",phase:1,topic:"1.4.1",qtype:"true-false",difficulty:1,stem:"In Lean, effectiveness means doing the right things — delivering the outcome the customer needs.",options:["True","False"],answer:0,hint:"Effectiveness = right things; efficiency = things done right.",steps:[{title:"Key idea",body:"**Effectiveness** = doing the **right things** (the outcome the customer needs). **Efficiency** = doing things **right** (least time, cost, effort)."},{title:"Apply to the stem",body:"The statement gives the effectiveness definition, so it is true. Lean wants both, starting with effectiveness."}],final:"The statement is true → answer **A**",whyWrong:["","Incorrect — this is the definition of effectiveness; doing things right with least effort is efficiency."],bookRef:"Syllabus 1.4.1"},{id:"sv-1-1191",phase:1,topic:"1.4.1",qtype:"sequence",difficulty:2,stem:`Put these steps of a value-added analysis in the usual order:

- **P** Apply the two value tests to each step
- **Q** List every step of the current process
- **R** Eliminate NVA steps and minimise BVA steps
- **S** Label each step VA, NVA or BVA`,options:["P → Q → S → R","Q → P → S → R","Q → S → P → R","Q → P → R → S"],answer:1,hint:"List → test → label → act.",steps:[{title:"Key idea",body:"First map (list) the steps; then apply the form-fit-function and customer-pays tests to each."},{title:"Apply to the stem",body:"The results give each step a label (VA, NVA, BVA); the labels then drive the action — eliminate NVA, minimise BVA."},{title:"Eliminate look-alikes",body:"So the order is Q → P → S → R."}],final:"Q → P → S → R → answer **B**",whyWrong:["Incorrect — the tests cannot be applied before the steps are listed.","","Incorrect — a step can only be labelled after the tests have been applied to it.","Incorrect — you act on the labels only after every step has been labelled."],bookRef:"Book p. 117"},{id:"sv-1-1192",phase:1,topic:"1.4.1",qtype:"concept",difficulty:1,stem:"In Lean thinking, what is the **value stream**?",options:["Only the value-added steps that remain after waste is removed","The flow of money from the customer back to the company","All the steps, end to end, that deliver the product or service to the customer","The list of critical-to-quality requirements stated by the customer"],answer:2,hint:"Second Lean principle: which steps deliver the value, end to end?",steps:[{title:"Key idea",body:"The **value stream** is every step, from request to delivery, that brings the product or service to the customer."},{title:"Apply to the stem",body:"It includes value-added and non-value-added steps; mapping it shows where the waste is."},{title:"Eliminate look-alikes",body:"Only-VA steps, money flow and CTQ lists are different things."}],final:"Value stream = all end-to-end steps → answer **C**",whyWrong:["Incorrect — the value stream includes every step, NVA ones too; that is why mapping it reveals waste.","Incorrect — the value stream follows the product or service, not the payment.","","Incorrect — CTQs describe what the customer requires, not the steps that deliver it."],bookRef:"Syllabus 1.4.1"},{id:"sv-1-1193",phase:1,topic:"1.4.2",qtype:"concept",difficulty:1,stem:"What does the Japanese word **kanban** mean, as used in the Toyota Production System?",options:["Waste, meaning activity that adds no value","Mistake-proofing, so an error cannot be made","Continual improvement of every process","A signal or card, usually a signal to begin work"],answer:3,hint:"Kanban controls pull production.",steps:[{title:"Key idea",body:"Book p. 511: kanban is the Japanese word for a communication **signal or card**, usually a signal to begin work."},{title:"Apply to the stem",body:"In TPS, kanban cards carry the pull signal from the next process."},{title:"Eliminate look-alikes",body:"Muda, poka-yoke and kaizen are other Japanese terms."}],final:"Kanban = signal/card → answer **D**",whyWrong:["Incorrect — waste is muda.","Incorrect — mistake-proofing is poka-yoke.","Incorrect — continual improvement is kaizen.",""],bookRef:"Book p. 511"},{id:"sv-1-1194",phase:1,topic:"1.4.2",qtype:"concept",difficulty:1,stem:"What is the aim of **jidoka**, one of the two pillars of the Toyota Production System?",options:["To stop when an abnormality appears so the problem is fixed at its source","To make only what is needed, when it is needed, in the amount needed","To cut die changeover time from hours to under ten minutes","To sort, arrange and clean the workplace in a standard way"],answer:0,hint:"JIT = right amount, right time; jidoka = stop and fix, build quality in.",steps:[{title:"Key idea",body:"**Jidoka** builds quality in at each step: when something abnormal appears, the line **stops** so the problem is fixed, not passed on."},{title:"Apply to the stem",body:"Its origin is Sakichi Toyoda’s loom that stopped itself when a thread broke."},{title:"Eliminate look-alikes",body:"JIT, SMED and 5S are different ideas."}],final:"Jidoka = stop and fix at source → answer **A**",whyWrong:["","Incorrect — this is Just-in-Time, the other pillar.","Incorrect — this is SMED, developed by Shigeo Shingo.","Incorrect — this describes 5S, not a TPS pillar."],bookRef:"Syllabus 1.4.2"},{id:"sv-1-1195",phase:1,topic:"1.4.2",qtype:"concept",difficulty:2,stem:"Why did the MIT researcher who coined the term choose the word **“lean”** for the Toyota way of working?",options:["Toyota employed far fewer engineers than its Western rivals","The system used less of everything — effort, space, inventory and time","The system was designed only for small, light vehicles","The system removed every inspector from the production line"],answer:1,hint:"“Lean” = less of everything.",steps:[{title:"Key idea",body:"In **1988 John Krafcik** used the word **“lean”** because the Toyota system used **less of everything** — effort, space, inventory and time."},{title:"Apply to the stem",body:"The word describes the whole system’s low use of resources."},{title:"Eliminate look-alikes",body:"Engineer numbers, car size and inspectors are not the reason."}],final:"Lean = less of everything → answer **B**",whyWrong:["Incorrect — the word was about using less of all resources, not about engineering headcount.","","Incorrect — “lean” describes the production system, not the size of the cars.","Incorrect — removing inspectors is not what the word refers to; quality was built in with jidoka."],bookRef:"Syllabus 1.4.2"},{id:"sv-1-1196",phase:1,topic:"1.4.2",qtype:"concept",difficulty:2,stem:"Long before the word “lean” was coined, which event sharply increased Western interest in the Toyota Production System?",options:["The opening of Ford’s Highland Park moving assembly line","The launch of Six Sigma at Motorola in the United States","The 1973 oil crisis, from which Toyota recovered faster than others","The publication of *Lean Thinking* by Womack and Jones"],answer:2,hint:"Toyota’s resilience in a crisis made the West look closely.",steps:[{title:"Key idea",body:"TPS was little known outside Japan until the **1973 oil crisis**, when Toyota recovered faster than other car makers."},{title:"Apply to the stem",body:"That performance gap drew attention to its methods."},{title:"Eliminate look-alikes",body:"The other events happened at different times or concern other methods."}],final:"1973 oil crisis → answer **C**",whyWrong:["Incorrect — Highland Park opened its moving line in 1913, long before TPS existed.","Incorrect — Six Sigma was launched at Motorola in the mid-1980s and is a separate method.","","Incorrect — *Lean Thinking* appeared in 1996, after Western interest was already high."],bookRef:"Syllabus 1.4.2"},{id:"sv-1-1197",phase:1,topic:"1.4.2",qtype:"concept",difficulty:2,stem:"Why was **SMED** (quick changeover) important to the Toyota Production System?",options:["It counted defects so that the line could be stopped","It sent a card upstream to signal that parts were needed","It moved cars past workers on a continuous line","It made small batches economical by cutting set-up time"],answer:3,hint:"Toyota needed many models in small volumes.",steps:[{title:"Key idea",body:"To make small batches pay, changeovers had to be fast. **Shigeo Shingo** developed SMED, cutting die changes from hours to under ten minutes."},{title:"Apply to the stem",body:"Fast changeovers let Toyota build variety in small lots without waste."},{title:"Eliminate look-alikes",body:"Jidoka, kanban and the moving line are other contributions."}],final:"SMED → small batches pay → answer **D**",whyWrong:["Incorrect — stopping on abnormality is jidoka, not a changeover method.","Incorrect — the upstream signal is kanban.","Incorrect — the moving line is Ford’s contribution.",""],bookRef:"Syllabus 1.4.2"},{id:"sv-1-1198",phase:1,topic:"1.4.2",qtype:"concept",difficulty:1,stem:"Where did Lean and Six Sigma each originate?",options:["Lean at Toyota in Japan; Six Sigma at Motorola in the USA","Lean at Motorola in the USA; Six Sigma at Toyota in Japan","Both at Toyota in Japan, as parts of the same system","Both at Ford in the USA, on the Model T assembly line"],answer:0,hint:"Toyota → Lean; Motorola → Six Sigma.",steps:[{title:"Key idea",body:"Lean grew from the **Toyota Production System** in Japan; Six Sigma came from **Motorola** in the USA."},{title:"Apply to the stem",body:"The book quiz distractor “Lean is Six Sigma that originated in South-East Asia” is wrong for this reason."},{title:"Eliminate look-alikes",body:"Swapped or shared origins are distractors."}],final:"Lean = Toyota/Japan; Six Sigma = Motorola/USA → answer **A**",whyWrong:["","Incorrect — the origins are swapped.","Incorrect — Six Sigma did not come from Toyota; it came from Motorola.","Incorrect — Ford gave flow, but neither Lean nor Six Sigma started there."],bookRef:"Syllabus 1.4.2"},{id:"sv-1-1199",phase:1,topic:"1.4.2",qtype:"concept",difficulty:3,stem:"Which contribution is credited to **Eiji Toyoda**?",options:["He invented an automatic loom that stopped itself when a thread broke","He visited Ford’s US plants in 1950 and, with Ohno, chose not to copy mass production","He founded the car company in 1937 and promoted just-in-time parts","He developed quick die changeover so small batches could pay"],answer:1,hint:"Sakichi = loom; Kiichiro = company and JIT; Eiji = Ford visit; Shingo = SMED.",steps:[{title:"Key idea",body:"In **1950 Eiji Toyoda** visited Ford’s plants. He and Taiichi Ohno decided that copying mass production would not work for Toyota."},{title:"Apply to the stem",body:"Toyota needed flow **with** variety and **without** waste."},{title:"Eliminate look-alikes",body:"The other contributions belong to Sakichi, Kiichiro and Shingo."}],final:"Eiji Toyoda = 1950 Ford visit → answer **B**",whyWrong:["Incorrect — the self-stopping loom was invented by Sakichi Toyoda.","","Incorrect — founding the car company and promoting JIT is credited to Kiichiro Toyoda.","Incorrect — quick changeover (SMED) was developed by Shigeo Shingo."],bookRef:"Syllabus 1.4.2"},{id:"sv-1-1200",phase:1,topic:"1.4.2",qtype:"concept",difficulty:2,stem:"Which statement about the Toyota Production System “house” is CORRECT?",options:["Just-in-Time and SMED form its two pillars","Jidoka means producing in large batches to forecast","Standardised work and kaizen sit beneath its two pillars","Kanban signals belong to the jidoka pillar"],answer:2,hint:"Two pillars (JIT, Jidoka) on a base of standard work and kaizen.",steps:[{title:"Key idea",body:"TPS is often drawn as a house with two pillars, **Just-in-Time** and **Jidoka**."},{title:"Apply to the stem",body:"Under both pillars sit **standardised work** and **kaizen**."},{title:"Eliminate look-alikes",body:"SMED supports JIT; kanban is part of JIT; jidoka is not batch production."}],final:"Base = standard work + kaizen → answer **C**",whyWrong:["Incorrect — the two pillars are Just-in-Time and Jidoka; SMED is a supporting method.","Incorrect — jidoka means stopping to fix problems at source; producing to forecast is push.","","Incorrect — kanban carries the pull signal, which belongs to the Just-in-Time pillar."],bookRef:"Syllabus 1.4.2"},{id:"sv-1-1201",phase:1,topic:"1.4.2",qtype:"concept",difficulty:2,stem:"Which statement about Lean outside manufacturing is CORRECT?",options:["Lean applies only to high-volume car assembly plants","In healthcare, Lean aims mainly to build larger stocks of supplies","Lean IT was the origin of the Toyota Production System","In offices, a pile of unprocessed cases is treated as inventory"],answer:3,hint:"In services, the “inventory” is information or cases waiting.",steps:[{title:"Key idea",body:"Once Lean was expressed as principles, it spread to **healthcare, services, offices and IT**."},{title:"Apply to the stem",body:"Banks, insurers and governments applied it to loans, claims and invoices, where the inventory is a pile of unprocessed cases."},{title:"Eliminate look-alikes",body:"The other statements limit Lean wrongly or reverse its history."}],final:"Office inventory = unprocessed cases → answer **D**",whyWrong:["Incorrect — once stated as principles, Lean spread to healthcare, services, offices and IT.","Incorrect — healthcare Lean reduces waiting, duplicated paperwork and movement, not adds stock.","Incorrect — TPS came from Toyota car making; Lean IT came much later.",""],bookRef:"Syllabus 1.4.2"},{id:"sv-1-1202",phase:1,topic:"1.4.2",qtype:"statements",difficulty:2,stem:`Which statements about **Taiichi Ohno** are CORRECT?

1. He built the Toyota Production System at Toyota.
2. He took the idea of pull from American supermarkets.
3. He invented the loom that stopped itself when a thread broke.
4. He first used the word “lean” in a 1988 article.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Ohno = TPS builder; loom = Sakichi; “lean” = Krafcik.",steps:[{title:"Key idea",body:"Statement 1 is true: Ohno and colleagues built TPS. Statement 2 is true: supermarkets that refill shelves on use inspired pull."},{title:"Apply to the stem",body:"Statement 3 belongs to Sakichi Toyoda; statement 4 belongs to John Krafcik."},{title:"Eliminate look-alikes",body:"So the correct pair is 1 and 2."}],final:"True: 1 and 2 → answer **A**",whyWrong:["","Incorrect — statement 3 is false: the self-stopping loom was Sakichi Toyoda’s.","Incorrect — statements 3 and 4 are both false.","Incorrect — statement 4 is false: “lean” was first used by John Krafcik in 1988."],bookRef:"Syllabus 1.4.2"},{id:"sv-1-1203",phase:1,topic:"1.4.2",qtype:"statements",difficulty:3,stem:`Which two statements about the pillars of the Toyota Production System are CORRECT?

1. Just-in-Time means the line stops when a defect appears.
2. Jidoka means producing large batches to a forecast.
3. Just-in-Time means making only what is needed, when it is needed.
4. Jidoka builds quality in by stopping to fix problems at their source.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Do not swap the pillars.",steps:[{title:"Key idea",body:"Statement 3 correctly defines **JIT**; statement 4 correctly defines **jidoka**."},{title:"Apply to the stem",body:"Statement 1 gives JIT the jidoka idea; statement 2 describes push production, which TPS avoids."},{title:"Eliminate look-alikes",body:"So the correct pair is 3 and 4."}],final:"True: 3 and 4 → answer **C**",whyWrong:["Incorrect — statements 1 and 2 are both false.","Incorrect — statement 2 is false and statement 3 alone is not enough.","","Incorrect — statement 1 is false: stopping the line is jidoka, not JIT."],trap:"The classic swap: “stop the line” is jidoka, “right amount at the right time” is JIT.",bookRef:"Syllabus 1.4.2"},{id:"sv-1-1204",phase:1,topic:"1.4.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Before Ford’s moving assembly line, cars were built by [?] production, with skilled workers fitting hand-made parts one car at a time.`,options:["batch","craft","lean","mass"],answer:1,hint:"What came before mass production?",steps:[{title:"Key idea",body:"Before the 20th century, cars were made by **craft production**: skilled workers fitted hand-made parts, one car at a time, with varying quality and high cost."},{title:"Apply to the stem",body:"Ford’s 1913 moving line replaced it with mass production."},{title:"Eliminate look-alikes",body:"Batch, lean and mass do not describe the hand-fitting era."}],final:"Craft production → answer **B**",whyWrong:["Incorrect — batch production makes groups of identical items; the sentence describes one-at-a-time hand fitting.","","Incorrect — lean production came much later, from Toyota.","Incorrect — mass production is what Ford’s moving line created, replacing the older method."],bookRef:"Syllabus 1.4.2"},{id:"sv-1-1205",phase:1,topic:"1.4.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

The 1996 book *Lean Thinking* restated Lean as five [?] that any organisation can apply.`,options:["belts","phases","pillars","principles"],answer:3,hint:"Value, value stream, flow, pull, perfection.",steps:[{title:"Key idea",body:"*Lean Thinking* (Womack and Jones, 1996) set out the **five principles**: value, value stream, flow, pull, perfection."},{title:"Apply to the stem",body:"Stating Lean as principles is what let it spread beyond car plants."},{title:"Eliminate look-alikes",body:"Belts, phases and pillars belong to other frameworks."}],final:"Five principles → answer **D**",whyWrong:["Incorrect — belts are Six Sigma practitioner levels.","Incorrect — phases describe DMAIC, not *Lean Thinking*.","Incorrect — pillars describe the TPS house (JIT and jidoka), and there are two, not five.",""],bookRef:"Syllabus 1.4.2"},{id:"sv-1-1206",phase:1,topic:"1.4.2",qtype:"not-except",difficulty:2,stem:"Which was NOT a feature of Ford’s mass production system?",options:["Easy switching between many models in small volumes","Very high volumes of one standard product","Interchangeable parts and short, standard tasks","Long production runs and large stocks of parts"],answer:0,hint:"Ford’s weakness was variety and change.",steps:[{title:"Key idea",body:"Ford proved the power of **flow**, but his system needed very high volumes of one product, long runs and large stocks."},{title:"Apply to the stem",body:"It **struggled with variety** — easy switching between many models is what Toyota had to invent."},{title:"Eliminate look-alikes",body:"The other three are true features of Ford’s system."}],final:"Variety was Ford’s weakness → answer **A**",whyWrong:["","Incorrect — high volume of one standard product was central to Ford’s system.","Incorrect — interchangeable parts and short standard tasks were key to the moving line.","Incorrect — long runs and big stocks were part of Ford’s system, and its weakness."],bookRef:"Syllabus 1.4.2"},{id:"sv-1-1207",phase:1,topic:"1.4.2",qtype:"not-except",difficulty:1,stem:"Which of these did NOT originate in Japan?",options:["Kaizen","The moving assembly line","Kanban","Poka-yoke"],answer:1,hint:"Which one did Henry Ford introduce in the USA?",steps:[{title:"Key idea",body:"Kaizen, kanban and poka-yoke are all **Japanese** terms (book pp. 503, 587)."},{title:"Apply to the stem",body:"The **moving assembly line** was introduced by Henry Ford at Highland Park, USA, in 1913."},{title:"Eliminate look-alikes",body:"So the non-Japanese item is the moving assembly line."}],final:"Moving line = Ford, USA → answer **B**",whyWrong:["Incorrect — kaizen is a Japanese term and practice from Toyota’s system.","","Incorrect — kanban is a Japanese term for the TPS pull signal.","Incorrect — poka-yoke is Japanese for mistake-proofing, linked to Shigeo Shingo."],bookRef:"Syllabus 1.4.2"},{id:"sv-1-1208",phase:1,topic:"1.4.2",qtype:"scenario",difficulty:2,stem:"A Green Belt explains that the team’s new board, which only lets an agent take a new ticket when a slot frees up, works like Toyota’s cards between processes. Which TPS pillar does this idea come from?",options:["Jidoka","Just-in-Time","Kaizen","Standardised work"],answer:1,hint:"Cards that trigger work on demand = kanban = pull.",steps:[{title:"Key idea",body:"Kanban cards carry the **pull** signal, which is part of the **Just-in-Time** pillar."},{title:"Apply to the stem",body:"A board that releases work only when capacity frees is the same idea."},{title:"Eliminate look-alikes",body:"Jidoka is the other pillar; kaizen and standardised work form the base."}],final:"Kanban pull → Just-in-Time → answer **B**",whyWrong:["Incorrect — jidoka is about stopping to fix abnormalities, not limiting work started.","","Incorrect — kaizen is the continual improvement base under both pillars, not a pillar itself.","Incorrect — standardised work is part of the base of the house, not a pillar."],bookRef:"Syllabus 1.4.2"},{id:"sv-1-1209",phase:1,topic:"1.4.2",qtype:"true-false",difficulty:2,stem:"Lean is a version of Six Sigma that originated in South-East Asia.",options:["True","False"],answer:1,hint:"Recall the origin of each method.",steps:[{title:"Key idea",body:"This is a book quiz distractor. Lean grew from the **Toyota Production System** in Japan."},{title:"Apply to the stem",body:"Six Sigma came from **Motorola** in the USA; Lean is not a version of it."}],final:"The statement is false → answer **B**",whyWrong:["Incorrect — Lean came from Toyota in Japan; Six Sigma came from Motorola in the USA. They have separate origins.",""],bookRef:"Syllabus 1.4.2"},{id:"sv-1-1210",phase:1,topic:"1.4.2",qtype:"sequence",difficulty:2,stem:`Put these events in **chronological** order:

- **P** Toyota’s fast recovery from the oil crisis draws Western attention
- **Q** Eiji Toyoda visits Ford’s plants in the USA
- **R** *Lean Thinking* sets out five principles
- **S** John Krafcik first uses the word “lean”`,options:["P → Q → S → R","Q → S → P → R","Q → P → S → R","Q → P → R → S"],answer:2,hint:"1950 → 1973 → 1988 → 1996.",steps:[{title:"Key idea",body:"Eiji Toyoda visited Ford in **1950**; the oil crisis was **1973**."},{title:"Apply to the stem",body:"Krafcik coined “lean” in **1988**; *Lean Thinking* followed in **1996**."},{title:"Eliminate look-alikes",body:"So the order is Q → P → S → R."}],final:"Q → P → S → R → answer **C**",whyWrong:["Incorrect — the Ford visit (1950) came before the oil crisis (1973).","Incorrect — Krafcik’s 1988 article came after the 1973 oil crisis.","","Incorrect — *Lean Thinking* (1996) came after Krafcik’s article (1988)."],bookRef:"Syllabus 1.4.2"},{id:"sv-1-1211",phase:1,topic:"1.4.2",qtype:"sequence",difficulty:3,stem:`Put these milestones in **chronological** order:

- **P** Toyota Motor is established as a car company
- **Q** Ford introduces the moving assembly line at Highland Park
- **R** Eiji Toyoda studies Ford’s US plants
- **S** Sakichi Toyoda’s Type G automatic loom appears`,options:["S → Q → P → R","Q → P → S → R","Q → S → R → P","Q → S → P → R"],answer:3,hint:"1913 → 1924 → 1937 → 1950.",steps:[{title:"Key idea",body:"Ford’s moving line: **1913**. Type G loom: **1924**."},{title:"Apply to the stem",body:"Toyota Motor established: **1937**. Eiji Toyoda visits Ford: **1950**."},{title:"Eliminate look-alikes",body:"So the order is Q → S → P → R."}],final:"Q → S → P → R → answer **D**",whyWrong:["Incorrect — Ford’s moving line (1913) came before the Type G loom (1924).","Incorrect — the loom (1924) came before the car company (1937).","Incorrect — the car company (1937) existed before Eiji’s visit (1950).",""],bookRef:"Syllabus 1.4.2"},{id:"sv-1-1212",phase:1,topic:"1.4.3",qtype:"concept",difficulty:2,stem:"What is the PRIMARY reason organisations combine Lean with Six Sigma?",options:["Speed without reliability, or reliability without speed, both fail the customer","Each method on its own is too expensive to train people in","Lean replaces Six Sigma once the defect rate reaches zero","Six Sigma is needed only to calculate the savings of Lean projects"],answer:0,hint:"Lean = speed and flow; Six Sigma = consistency.",steps:[{title:"Key idea",body:"A desk that closes tickets fast but reopens many only moves waste around; a perfectly consistent five-day repair is still five days."},{title:"Apply to the stem",body:"Lean fixes speed and waste; Six Sigma fixes variation and defects. The customer needs both."},{title:"Eliminate look-alikes",body:"Cost, replacement and “calculator” roles misstate the partnership."}],final:"Customers need both speed and reliability → answer **A**",whyWrong:["","Incorrect — cost of training is not the reason; the methods solve different halves of the problem.","Incorrect — they are partners, not stages; neither replaces the other.","Incorrect — Six Sigma’s role is reducing variation and defects, not costing Lean projects."],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1213",phase:1,topic:"1.4.3",qtype:"concept",difficulty:1,stem:"Which kind of problem does **Lean** mainly attack?",options:["Results that are unpredictable because of variation","Results that are slow or costly because of waste","Results that drift because the gauge is unreliable","Results that miss because the project goal is unclear"],answer:1,hint:"Waste makes things slow or costly; variation makes them unpredictable.",steps:[{title:"Key idea",body:"**Lean** attacks **waste and delay** to make work faster and smoother."},{title:"Apply to the stem",body:"Six Sigma attacks variation, which makes results unpredictable."},{title:"Eliminate look-alikes",body:"Gauge and goal problems belong to MSA and the charter."}],final:"Lean → waste, slow/costly → answer **B**",whyWrong:["Incorrect — unpredictable results from variation are the focus of Six Sigma.","","Incorrect — an unreliable gauge is a measurement system (MSA) problem.","Incorrect — an unclear goal is a charter problem in Define."],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1214",phase:1,topic:"1.4.3",qtype:"concept",difficulty:2,stem:"In Six Sigma, what does the expression **Y = f(X)** describe?",options:["The yield equals the fraction of defective units","The cost of a step depends only on its time","The output depends on the inputs that drive it","The value of a step is what the business decides"],answer:2,hint:"Y is the output; X’s are the inputs that cause it.",steps:[{title:"Key idea",body:"Six Sigma asks: what is the output **Y**, and which inputs **X** drive it? Hence $Y = f(X)$."},{title:"Apply to the stem",body:"Finding and controlling the critical X’s controls the Y."},{title:"Eliminate look-alikes",body:"Yield, step cost and business value are not what the expression means."}],final:"Y = f(X): output is a function of inputs → answer **C**",whyWrong:["Incorrect — yield is a separate measure; Y here is any process output.","Incorrect — this is not the Six Sigma transfer function; it limits inputs to time.","","Incorrect — value is defined by the customer, and this is not what Y = f(X) expresses."],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1215",phase:1,topic:"1.4.3",qtype:"concept",difficulty:2,stem:"In a Lean Six Sigma project, which tool is used in the **Measure** phase to show where waiting and hand-offs sit across the end-to-end process?",options:["Control plan","Project charter","Cause-and-effect diagram","Value stream map"],answer:3,hint:"Lean tool + Measure phase + end-to-end view of waste.",steps:[{title:"Key idea",body:"In Lean Six Sigma, the **value stream map** is a Measure item: it baselines lead time and shows where work waits."},{title:"Apply to the stem",body:"The stem asks for the end-to-end picture of waiting and hand-offs, which is what the map shows."},{title:"Eliminate look-alikes",body:"Charter, cause-and-effect diagram and control plan belong to other phases and purposes."}],final:"Measure + end-to-end waste view = value stream map → answer **D**",whyWrong:["Incorrect — the control plan is a Control-phase document for holding the gains.","Incorrect — the charter is written in Define to set the problem, goal and scope.","Incorrect — the cause-and-effect diagram explores possible causes, mainly in Analyze.",""],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1216",phase:1,topic:"1.4.3",qtype:"concept",difficulty:2,stem:"How are Lean tools used within a Lean Six Sigma project?",options:["By applying them inside the DMAIC phases wherever they help","By running them only after the Control phase has closed","By replacing DMAIC with a kaizen event in every case","By using them only on processes that have no data"],answer:0,hint:"DMAIC backbone + Lean tools inside.",steps:[{title:"Key idea",body:"In Lean Six Sigma, **DMAIC stays the backbone** and Lean tools are used wherever they help."},{title:"Apply to the stem",body:"Book p. 501: Lean tools can be used at any time — before, during or after a project."},{title:"Eliminate look-alikes",body:"The other options restrict Lean tools wrongly or drop DMAIC."}],final:"Lean tools inside DMAIC → answer **A**",whyWrong:["","Incorrect — the book says Lean tools can be used at any time, not only after Control.","Incorrect — DMAIC stays the backbone; kaizen events suit only visible-waste problems.","Incorrect — Lean tools are used with data too, for example lead time and WIP."],bookRef:"Book p. 501"},{id:"sv-1-1217",phase:1,topic:"1.4.3",qtype:"concept",difficulty:2,stem:"Against what does Six Sigma mainly judge whether a process result is a **defect**?",options:["The fastest lead time of a competitor","The customer’s CTQ specification limits","The average output of the previous year","The improvement goal set by the team"],answer:1,hint:"Defect = result outside what the customer requires.",steps:[{title:"Key idea",body:"Six Sigma judges how consistently a process meets **customer requirements**: a defect is a result outside the **CTQ specification limits**."},{title:"Apply to the stem",body:"Variation matters because it pushes results outside those limits."},{title:"Eliminate look-alikes",body:"Benchmarks, baselines and goals are useful references but do not define a defect."}],final:"Defect = outside CTQ limits → answer **B**",whyWrong:["Incorrect — a competitor’s lead time is a benchmark, not the definition of a defect.","","Incorrect — last year’s average is a baseline for improvement, not a defect limit.","Incorrect — the project goal is a target for improvement, not a customer specification."],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1218",phase:1,topic:"1.4.3",qtype:"concept",difficulty:1,stem:"In a Lean Six Sigma project, in which phase are 5S, visual management and standard work used alongside control charts to **hold the gains**?",options:["Define","Measure","Analyze","Control"],answer:3,hint:"Which phase sustains the improvement?",steps:[{title:"Key idea",body:"Lean tools appear in every phase. In **Control**, 5S, visual management, standard work and control charts hold the gains."},{title:"Apply to the stem",body:"The stem’s purpose is sustaining — that is Control."},{title:"Eliminate look-alikes",body:"Define, Measure and Analyze come before there is a gain to hold."}],final:"Hold the gains = Control → answer **D**",whyWrong:["Incorrect — Define sets VOC, value and the charter; gains do not yet exist.","Incorrect — Measure sets the baseline, for example with a value stream map.","Incorrect — Analyze separates waste causes from variation causes.",""],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1219",phase:1,topic:"1.4.3",qtype:"concept",difficulty:2,stem:"Why do non-value-added steps matter to a Six Sigma practitioner?",options:["They raise the price the customer is willing to pay","They reduce the number of defect opportunities","Each extra step adds another opportunity for a defect","They make process capability easier to measure"],answer:2,hint:"An extra manual re-entry is waste — and a new chance for an error.",steps:[{title:"Key idea",body:"Every non-value-added step adds delay **and** another opportunity for a defect."},{title:"Apply to the stem",body:"Example: a manual re-entry step is waste, and also a chance for a typing error that creates variation."},{title:"Eliminate look-alikes",body:"That is why removing waste supports Six Sigma goals."}],final:"NVA steps = more defect opportunities → answer **C**",whyWrong:["Incorrect — NVA steps by definition add nothing the customer would pay for.","Incorrect — extra steps add opportunities for error, they do not remove them.","","Incorrect — extra steps do not help capability measurement; they add variation."],bookRef:"Book p. 502"},{id:"sv-1-1220",phase:1,topic:"1.4.3",qtype:"concept",difficulty:1,stem:"Which statement about Lean and Six Sigma is CORRECT?",options:["Lean improvements always need a hypothesis test before any change","Six Sigma projects are usually quicker than Lean quick wins","Six Sigma projects do not follow a structured roadmap","Many Lean improvements need little statistics because the waste is visible"],answer:3,hint:"Visible waste vs hidden variation.",steps:[{title:"Key idea",body:"Lean results often come quickly and need **little statistics**, because the waste is obvious once the process is seen clearly."},{title:"Apply to the stem",body:"Six Sigma is data-driven, follows DMAIC and usually takes longer."},{title:"Eliminate look-alikes",body:"The other statements reverse these facts."}],final:"Lean: often little statistics → answer **D**",whyWrong:["Incorrect — a ticket that waits 90 minutes for nobody needs no hypothesis test.","Incorrect — Six Sigma projects usually take longer, because hidden causes need evidence.","Incorrect — Six Sigma follows the structured DMAIC roadmap.",""],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1221",phase:1,topic:"1.4.3",qtype:"concept",difficulty:3,stem:"Which statement about sustaining the gains of a Six Sigma project is CORRECT?",options:["Lean tools add the discipline needed to sustain Six Sigma gains","Six Sigma gains sustain themselves once capability is shown","Lean tools should be removed once the project is closed","Sustaining the gains is the task of Finance, not the process"],answer:0,hint:"Book p. 502: Lean tools and sustaining.",steps:[{title:"Key idea",body:"Book p. 502: **Lean tools add the discipline needed to sustain gains** from Six Sigma projects."},{title:"Apply to the stem",body:"Without them, wastes and outliers can return."},{title:"Eliminate look-alikes",body:"Gains do not hold by themselves, and Finance does not run the process."}],final:"Lean discipline sustains gains → answer **A**",whyWrong:["","Incorrect — the book warns that wastes and outliers can come back without Lean discipline.","Incorrect — removing the tools invites the old waste back.","Incorrect — the process owner sustains the gains; Finance records the realised benefit."],bookRef:"Book p. 502"},{id:"sv-1-1222",phase:1,topic:"1.4.3",qtype:"statements",difficulty:1,stem:`Which statements about Lean and Six Sigma are CORRECT?

1. Waste makes results slow or costly.
2. Lean and Six Sigma must be used on separate processes.
3. Six Sigma ignores customer requirements.
4. Variation makes results unpredictable.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Waste → slow/costly; variation → unpredictable.",steps:[{title:"Key idea",body:"Statements 1 and 4 give the simple test for telling the problems apart."},{title:"Apply to the stem",body:"Statement 2 is false (they are partners), and statement 3 is false (defects are judged against CTQ limits)."},{title:"Eliminate look-alikes",body:"So the correct pair is 1 and 4."}],final:"True: 1 and 4 → answer **D**",whyWrong:["Incorrect — statement 2 is false: they work together on the same process.","Incorrect — statements 2 and 3 are both false.","Incorrect — statement 3 is false: Six Sigma measures against customer CTQs.",""],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1223",phase:1,topic:"1.4.3",qtype:"statements",difficulty:3,stem:`Which statements about choosing an improvement approach are CORRECT?

1. A known cause with a cheap fix should go through a full DMAIC project.
2. Visible waste such as queues and hand-offs suits a kaizen event.
3. An unknown cause of inconsistent output, with data available, suits DMAIC.
4. Lean Six Sigma is used only when a process is already capable.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Match the approach to how visible the cause is.",steps:[{title:"Key idea",body:"Statement 2 is true: visible waste → Lean tools or a kaizen event. Statement 3 is true: unknown cause of inconsistency with data → DMAIC."},{title:"Apply to the stem",body:"Statement 1 is false (just do it). Statement 4 is false (LSS is for slow and inconsistent processes)."},{title:"Eliminate look-alikes",body:"So the correct pair is 2 and 3."}],final:"True: 2 and 3 → answer **B**",whyWrong:["Incorrect — statement 1 is false: a known cause and cheap fix is a “just do it”.","","Incorrect — statement 4 is false: Lean Six Sigma suits slow and inconsistent, high-impact problems.","Incorrect — statements 1 and 4 are both false."],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1224",phase:1,topic:"1.4.3",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

In Lean Six Sigma, [?] stays the backbone of the project and Lean tools are used inside it.`,options:["5S","DMAIC","kaizen","kanban"],answer:1,hint:"Which roadmap structures the project?",steps:[{title:"Key idea",body:"In Lean Six Sigma, **DMAIC** is the backbone; Lean tools are used wherever they help."},{title:"Apply to the stem",body:"So the missing word is DMAIC."},{title:"Eliminate look-alikes",body:"5S, kaizen and kanban are Lean ideas used inside it."}],final:"DMAIC = backbone → answer **B**",whyWrong:["Incorrect — 5S is a Lean tool used inside the project, mainly to organise and sustain.","","Incorrect — kaizen is the improvement philosophy; it is not the project roadmap.","Incorrect — kanban is a pull signal, a tool inside the project."],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1225",phase:1,topic:"1.4.3",qtype:"not-except",difficulty:1,stem:"Which is NOT a typical Lean measure?",options:["Lead time","Defects per million opportunities","Work in progress","Throughput"],answer:1,hint:"Lean measures speed and flow; Six Sigma measures defects and capability.",steps:[{title:"Key idea",body:"Typical Lean measures: **lead time, work in progress, process efficiency, throughput**."},{title:"Apply to the stem",body:"DPMO is a typical **Six Sigma** measure, with yield, sigma level and Cp/Cpk."},{title:"Eliminate look-alikes",body:"So DPMO is the odd one out."}],final:"DPMO is a Six Sigma measure → answer **B**",whyWrong:["Incorrect — lead time is a core Lean measure of speed.","","Incorrect — work in progress is a core Lean measure of flow.","Incorrect — throughput is a core Lean measure of output rate."],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1226",phase:1,topic:"1.4.3",qtype:"not-except",difficulty:2,stem:"The book lists signs that the Lean concepts are needed to sustain a Six Sigma project. Which is NOT one of them?",options:["Outliers appearing in the process data","Benefits declining after the project closed","Capability rising steadily after go-live","Capability falling after go-live"],answer:2,hint:"Book p. 513: outliers, declining benefits, falling capability.",steps:[{title:"Key idea",body:"Book p. 513: if you see **outliers, declining benefits or falling capability**, the five Lean concepts help sustain the project."},{title:"Apply to the stem",body:"Rising capability is good news, not a warning sign."},{title:"Eliminate look-alikes",body:"The other three are the book’s warning signs."}],final:"Rising capability is not a warning sign → answer **C**",whyWrong:["Incorrect — outliers are a listed warning sign.","Incorrect — declining benefits are a listed warning sign.","","Incorrect — falling capability is a listed warning sign."],bookRef:"Book p. 513"},{id:"sv-1-1227",phase:1,topic:"1.4.3",qtype:"scenario",difficulty:2,stem:"On a machining line, the diameter of a drilled hole drifts outside tolerance on some parts but not others. Nobody knows why, and measurement data are available. Which approach fits BEST?",options:["A Lean kaizen event to remove waiting between machines","An immediate fix, because the cause is already known","A 5S event to sort and clean the machining area","A Six Sigma DMAIC project to find the source of variation"],answer:3,hint:"Unknown cause + inconsistency + data → DMAIC.",steps:[{title:"Key idea",body:"Variation makes results unpredictable; a hidden cause needs evidence — **Six Sigma (DMAIC)**."},{title:"Apply to the stem",body:"A drifting diameter with an unknown cause and available data fits exactly."},{title:"Eliminate look-alikes",body:"Waste removal, just-do-it and 5S do not address a hidden variation cause."}],final:"Hidden variation → DMAIC → answer **D**",whyWrong:["Incorrect — waiting is waste; the problem here is unpredictable dimensions.","Incorrect — the stem says nobody knows the cause, so there is no known fix.","Incorrect — 5S organises the workplace; it does not find a hidden cause of variation.",""],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1228",phase:1,topic:"1.4.3",qtype:"scenario",difficulty:2,stem:"In a hospital, patients wait several hours for a bed after their discharge has been approved. The delay happens the same way every day and its cause is visible. Which lens should the team apply FIRST?",options:["Lean, because the problem is visible waiting","Six Sigma, because the problem is hidden variation","Six Sigma, because waiting is a type of defect","Neither, because waiting cannot be improved"],answer:0,hint:"Consistent, visible delay = waste.",steps:[{title:"Key idea",body:"Consistent, visible delays are **waste (waiting)** — a Lean problem."},{title:"Apply to the stem",body:"The book lesson’s table lists exactly this case: patients waiting for a bed → Lean."},{title:"Eliminate look-alikes",body:"Six Sigma is the first lens when results are inconsistent and the cause is hidden."}],final:"Visible waiting → Lean first → answer **A**",whyWrong:["","Incorrect — the delay is consistent and visible, not a hidden variation problem.","Incorrect — waiting is a waste, not a defect against a specification.","Incorrect — waiting is one of the wastes Lean removes routinely."],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1229",phase:1,topic:"1.4.3",qtype:"scenario",difficulty:3,stem:"An order is typed into one system and then **re-typed by hand** into a second system. The step adds delay, and the re-typing also creates random keying errors. Which statement BEST describes this step?",options:["It is both waste and a source of defects, so Lean and Six Sigma both apply","It is waste only, so Six Sigma has no role in fixing it","It is variation only, so Lean has no role in fixing it","It is value-added, because the errors are corrected later"],answer:0,hint:"An extra manual step is waste — and a new chance for an error.",steps:[{title:"Key idea",body:"The book links the two: an extra manual re-entry step is **waste** and also a new chance for a typing error that creates **variation**."},{title:"Apply to the stem",body:"So both lenses apply — Lean to remove the step, Six Sigma to understand and prevent the errors."},{title:"Eliminate look-alikes",body:"Choosing only one lens, or calling it value-added, misreads the step."}],final:"Waste + defects → both apply → answer **A**",whyWrong:["","Incorrect — the keying errors create variation and defects, which Six Sigma addresses.","Incorrect — the extra step is waste (delay), which Lean addresses.","Incorrect — re-entry is a “re-” activity; correcting errors later is also waste."],bookRef:"Book p. 502"},{id:"sv-1-1230",phase:1,topic:"1.4.3",qtype:"scenario",difficulty:3,stem:"Before a Green Belt studies the capability of restore times, the team uses Lean tools to clear a chaotic backlog and remove obvious hand-off waste. What is the main reason for doing this first?",options:["To avoid the need for a measurement system analysis","To stabilise the process so the data reflect its real behaviour","To make the capability study unnecessary","To raise the process mean before measuring it"],answer:1,hint:"Book quiz: the Lean toolbox stabilises a process.",steps:[{title:"Key idea",body:"The book (p. 501) says Belts use Lean tools to **clean up a process before, during or after** a project; the book quiz says the Lean toolbox **stabilises** a process."},{title:"Apply to the stem",body:"A stable process gives data that reflect how it really behaves, so capability results mean something."},{title:"Eliminate look-alikes",body:"Lean clean-up does not replace MSA or the capability study."}],final:"Stabilise first → answer **B**",whyWrong:["Incorrect — measurement system analysis is still needed; Lean clean-up does not validate the gauge.","","Incorrect — the capability study is still done; Lean tools prepare the process for it.","Incorrect — the aim is a stable process, not a shifted mean."],bookRef:"Book p. 582"},{id:"sv-1-1231",phase:1,topic:"1.4.3",qtype:"best-action",difficulty:3,stem:`Many orders are rejected because a mandatory field is missing from an online form. Everyone agrees that adding the field will fix it, at almost no cost. The manager asks a Green Belt to launch a full DMAIC project.

Was this an appropriate action?`,options:["Yes, because every improvement must follow the DMAIC roadmap","Yes, because rejected orders are defects that need statistics","No, because a known cause with a cheap fix should just be implemented","No, because form problems are handled only by kaizen events"],answer:2,hint:"Known cause + cheap, low-risk fix → just do it.",steps:[{title:"Key idea",body:"When the cause and the fix are both obvious, low risk and cheap, the best fit is **just do it** — implement and confirm."},{title:"Apply to the stem",body:"Launching DMAIC would spend months proving what everyone already knows."},{title:"Eliminate look-alikes",body:"So the action was not appropriate."}],final:"Just do it, then confirm → answer **C**",whyWrong:["Incorrect — not every problem needs a four-month DMAIC project.","Incorrect — they are defects, but with the cause and fix known no statistical search is needed.","","Incorrect — there is no rule tying forms to kaizen events; here even a kaizen event is unnecessary."],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1232",phase:1,topic:"1.4.3",qtype:"best-action",difficulty:3,stem:`Bills for the same tariff sometimes show amounts that differ from what the rating rules should produce. The errors appear at random-looking times, nobody knows the cause, and months of billing data exist. The Green Belt launches a DMAIC project instead of a one-day kaizen event.

Was this an appropriate action?`,options:["Yes, because the problem is inconsistency with an unknown cause and data to analyse","Yes, because DMAIC is required for every problem in a billing process","No, because Lean tools must always be used before any DMAIC project","No, because billing errors are a waste problem that kaizen removes"],answer:0,hint:"Unknown cause + inconsistency + data → DMAIC.",steps:[{title:"Key idea",body:"DMAIC fits when the **cause is unknown**, the problem is **inconsistency or defects**, and **data are available**."},{title:"Apply to the stem",body:"Random-looking billing differences with an unknown cause and months of data match all three."},{title:"Eliminate look-alikes",body:"So the action was appropriate, for that reason."}],final:"Hidden cause of defects → DMAIC was right → answer **A**",whyWrong:["","Incorrect — DMAIC is not required for every problem; known causes are just fixed.","Incorrect — Lean tools can be used at any time, but there is no rule that they must come first.","Incorrect — random errors with a hidden cause are a variation problem, not visible waste."],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1233",phase:1,topic:"1.4.3",qtype:"best-action",difficulty:2,stem:"A Lean Six Sigma team has finished Improve. Lead time and defect rates have both fallen. What is the BEST way to hold these gains?",options:["Rely on control charts alone and drop the Lean tools","Remove the Lean tools so staff are not confused by them","Combine control charts with 5S, visual management and standard work","Repeat the Measure phase to recalculate the baseline"],answer:2,hint:"Control = Lean sustaining tools + statistical monitoring.",steps:[{title:"Key idea",body:"In Lean Six Sigma Control, **5S, visual management, standard work and control charts** work together."},{title:"Apply to the stem",body:"Book p. 502: Lean tools add the discipline needed to sustain Six Sigma gains."},{title:"Eliminate look-alikes",body:"Charts alone, removing tools or re-measuring the baseline do not hold the gains."}],final:"Both Lean and statistical control → answer **C**",whyWrong:["Incorrect — control charts show stability, but the book says Lean discipline is needed to sustain gains.","Incorrect — removing Lean tools invites waste and outliers to return.","","Incorrect — the baseline is already set; Control is about sustaining the new level."],bookRef:"Book p. 502"},{id:"sv-1-1234",phase:1,topic:"1.4.3",qtype:"output",difficulty:3,stem:`A team reviews a provisioning process. The customer requirement is activation within 48 hours.

\`\`\`
Descriptive Statistics: Activation time (hours)

N     Mean   StDev   Minimum   Maximum
120   22.4   14.9       2.1      79.6

Waiting share of lead time: 12%
% beyond 48 h: 6.7%
\`\`\`

Which approach should lead the improvement?`,options:["Lean, because the mean is far above the 48-hour requirement","Lean, because waiting is the largest share of the lead time","Neither, because no orders take longer than 48 hours","Six Sigma, because the spread is wide while waiting is a small share"],answer:3,hint:"Waste makes the average long; variation makes results unpredictable.",steps:[{title:"Key idea",body:"Read the output: the mean is comfortably inside the requirement, but StDev is large and the maximum reaches 79.6 h."},{title:"Apply to the stem",body:"Waiting is only 12% of lead time, so this is mainly a **variation** problem → Six Sigma leads."},{title:"Eliminate look-alikes",body:"The other options misread the mean, the waiting share or the late percentage."}],final:"Wide spread, short mean → Six Sigma → answer **D**",whyWrong:["Incorrect — the mean (22.4 h) is well inside 48 h; slowness on average is not the issue.","Incorrect — the output prints waiting as only 12% of lead time.","Incorrect — the output prints 6.7% of orders beyond 48 h, and a maximum of 79.6 h.",""],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1235",phase:1,topic:"1.4.3",qtype:"output",difficulty:3,stem:`A value stream summary for enterprise quotes shows:

\`\`\`
Value Stream Summary: Enterprise quote process

Lead time (mean)            9.5 days
Value-added time (mean)     3.2 hours
Waiting share of lead time  91%
Defects                     180 DPMO
StDev of lead time          0.6 days
\`\`\`

Which approach should lead the improvement?`,options:["Lean, because the delay is mostly waiting and the process is consistent","Six Sigma, because the defect rate is far too high for the customer","Six Sigma, because the lead time varies widely from quote to quote","Neither, because value-added time is already short"],answer:0,hint:"Read the waiting share and the spread.",steps:[{title:"Key idea",body:"The output shows **91% waiting** in a consistent process (small StDev) with few defects."},{title:"Apply to the stem",body:"Waste that makes the average too long is a Lean problem."},{title:"Eliminate look-alikes",body:"The other options misread the DPMO, the StDev or the VA time."}],final:"Mostly waiting, consistent → Lean → answer **A**",whyWrong:["","Incorrect — 180 DPMO is a low defect rate; defects are not the main problem.","Incorrect — StDev of lead time is printed as only 0.6 days; the process is consistent.","Incorrect — short VA time inside a 9.5-day lead time means poor flow, which Lean fixes."],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1236",phase:1,topic:"1.4.3",qtype:"output",difficulty:3,stem:`Fault restore times are compared by shift. The SLA is 4 hours.

\`\`\`
Descriptive Statistics: Restore time (hours)

Shift   N    Mean   StDev   Waiting share
Day     85   6.1    0.8        78%
Night   80   6.4    3.9        74%
\`\`\`

Which conclusion is BEST supported?`,options:["Only Night has a problem, because only its StDev is large","Both shifts are slow mainly from waiting, and Night is also inconsistent, so Lean Six Sigma fits","Only Day has a problem, because its waiting share is higher","Neither shift has a problem, because the means are almost equal"],answer:1,hint:"Long mean → Lean; wide spread → Six Sigma; both → Lean Six Sigma.",steps:[{title:"Key idea",body:"Both means are above the 4-hour SLA, and most of the time is waiting — a **Lean** problem on both shifts."},{title:"Apply to the stem",body:"Night’s StDev (3.9) is far larger than Day’s (0.8), so Night also has a **variation** problem."},{title:"Eliminate look-alikes",body:"Slow and inconsistent together point to **Lean Six Sigma**."}],final:"Slow + inconsistent → Lean Six Sigma → answer **B**",whyWrong:["Incorrect — Day’s mean of 6.1 h is also above the 4-hour SLA, mostly from waiting.","","Incorrect — Night has a similar waiting share and a much larger StDev as well.","Incorrect — equal means do not help when both are above the SLA."],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1237",phase:1,topic:"1.4.3",qtype:"true-false",difficulty:1,stem:"The course book states that “a Six Sigma project is actually a Kaizen”.",options:["True","False"],answer:0,hint:"Book p. 510 links kaizen and Six Sigma projects.",steps:[{title:"Key idea",body:"Book p. 510: **“A Six Sigma project is actually a Kaizen.”**"},{title:"Apply to the stem",body:"It also calls breakthrough successes **kaikaku**, the first focus of Six Sigma projects."}],final:"The statement is true → answer **A**",whyWrong:["","Incorrect — the book (p. 510) does say this; it calls kaizens Six Sigma projects with business impact."],bookRef:"Book p. 510"},{id:"sv-1-1238",phase:1,topic:"1.4.3",qtype:"true-false",difficulty:2,stem:"Lean tools should be used only in the Control phase of a Six Sigma project.",options:["True","False"],answer:1,hint:"Book p. 501 on when Lean tools are used.",steps:[{title:"Key idea",body:"Book p. 501: Lean tools can be used **at any time** in a project — to reduce variation, deal with outliers or clean up a process before, during or after it."},{title:"Apply to the stem",body:"So limiting them to Control is wrong."}],final:"The statement is false → answer **B**",whyWrong:["Incorrect — the book says Lean tools can be used at any time, before, during or after a project.",""],bookRef:"Book p. 501"},{id:"sv-1-1239",phase:1,topic:"1.4.3",qtype:"sequence",difficulty:2,stem:`In a Lean Six Sigma project, put these activities in DMAIC order:

- **P** Build a value stream map to baseline lead time
- **Q** Write a charter whose primary metric captures the waste
- **R** Introduce pull and mistake-proofing with tested solutions
- **S** Use 5S, standard work and control charts to hold the gains`,options:["P → Q → R → S","Q → R → P → S","Q → P → R → S","Q → P → S → R"],answer:2,hint:"Define → Measure → (Analyze) → Improve → Control.",steps:[{title:"Key idea",body:"Define: charter with a primary metric (Q). Measure: value stream map baseline (P)."},{title:"Apply to the stem",body:"Improve: pull and mistake-proofing (R). Control: 5S, standard work, control charts (S)."},{title:"Eliminate look-alikes",body:"So the order is Q → P → R → S."}],final:"Q → P → R → S → answer **C**",whyWrong:["Incorrect — the charter (Define) comes before the baseline map (Measure).","Incorrect — the baseline map (Measure) comes before introducing solutions (Improve).","","Incorrect — gains are held (Control) only after solutions are introduced (Improve)."],bookRef:"Syllabus 1.4.3"},{id:"sv-1-1240",phase:1,topic:"1.4.4",qtype:"scenario",difficulty:2,stem:"The marketing team prints **10,000** brochures for a new tariff, although shops expect to hand out about 3,000. The tariff is withdrawn after a month and most of the brochures are recycled. Which of the seven elements of waste BEST describes the root waste?",options:["Inventory","Overprocessing","Overproduction","Waiting"],answer:2,hint:"Too many, too soon → which element?",steps:[{title:"Key idea",body:"**Overproduction** = making more, or earlier, than the next step needs. It is often called the worst waste because it creates others."},{title:"Apply to the stem",body:"Printing far more than the expected demand is overproduction; the stored surplus (inventory) is its consequence."},{title:"Eliminate look-alikes",body:"Overprocessing is about effort per item, and nothing is waiting."}],final:"More than needed = Overproduction → answer **C**",whyWrong:["Incorrect — the boxes in storage are inventory, but the root waste is making more than was needed.","Incorrect — overprocessing is too much work on each item, not too many items.","","Incorrect — waiting is people or work idle; nothing is held up here."],trap:"The pile of unused brochures is Inventory, but the question asks for the root waste: making too many.",bookRef:"Book p. 502"}];export{e as items};
